func BeginAuthnLogin(c *gin.Context) {
	enabled := setting.GetBool(conf.WebauthnLoginEnabled)
	if !enabled {
		common.ErrorStrResp(c, "WebAuthn is not enabled", 403)
		return
	}
	authnInstance, err := authn.NewAuthnInstance(c)
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	var (
		options		*protocol.CredentialAssertion
		sessionData	*webauthn.SessionData
	)
	if username := c.Query("username"); username != "" {
		var user *model.User
		user, err = db.GetUserByName(username)
		if err == nil {
			options, sessionData, err = authnInstance.BeginLogin(user)
		}
	} else {
		options, sessionData, err = authnInstance.BeginDiscoverableLogin()
	}
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	val, err := json.Marshal(sessionData)
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}
	common.SuccessResp(c, gin.H{
		"options":	options,
		"session":	val,
	})
}

func BeginAuthnRegistration(c *gin.Context) {
	enabled := setting.GetBool(conf.WebauthnLoginEnabled)
	if !enabled {
		common.ErrorStrResp(c, "WebAuthn is not enabled", 403)
		return
	}
	user := c.Request.Context().Value(conf.UserKey).(*model.User)

	authnInstance, err := authn.NewAuthnInstance(c)
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	options, sessionData, err := authnInstance.BeginRegistration(
		user,
		webauthn.WithResidentKeyRequirement(protocol.ResidentKeyRequirementRequired),
	)

	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	val, err := json.Marshal(sessionData)
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	common.SuccessResp(c, gin.H{
		"options":	options,
		"session":	val,
	})
}

func BuildIndex(c *gin.Context) {
	if search.Running() {
		common.ErrorStrResp(c, "index is running", 400)
		return
	}
	go func() {
		ctx := context.Background()
		err := search.Clear(ctx)
		if err != nil {
			log.Errorf("clear index error: %+v", err)
			return
		}
		err = search.BuildIndex(context.Background(), []string{"/"},
			conf.SlicesMap[conf.IgnorePaths], setting.GetInt(conf.MaxIndexDepth, 20), true)
		if err != nil {
			log.Errorf("build index error: %+v", err)
		}
	}()
	common.SuccessResp(c)
}

// CanUserAccessItem 判断用户是否可访问某个媒体条目（含所属媒体类型开关）
func CanUserAccessItem(user *model.User, item *model.MediaItem) bool {
	if item == nil || item.Hidden {
		return false
	}
	if !MediaTypeEnabled(item.MediaType) {
		return false
	}
	return CanUserAccessPath(user, MediaItemFilePath(item))
}

// CanUserAccessPath 判断用户是否有权访问指定 VFS 路径
// 规则与文件浏览保持一致：base_path 前缀 + 元信息(meta) 读权限 + 隐藏文件规则。
//
// user 为 nil 一律拒绝（fail-closed）：所有调用点都应经过 Auth / embyAuth 拿到用户，
// 缺失用户说明鉴权链路出了问题，不能默认放行；被禁用的访客同样拒绝。
func CanUserAccessPath(user *model.User, reqPath string) bool {
	if user == nil || (user.IsGuest() && user.Disabled) {
		return false
	}
	reqPath = utils.FixAndCleanPath(reqPath)
	base := utils.FixAndCleanPath(user.BasePath)
	if base == "" {
		base = "/"
	}
	if base != "/" && !utils.IsSubPath(base, reqPath) && !utils.PathEqual(base, reqPath) {
		return false
	}
	meta, err := op.GetNearestMeta(reqPath)
	if err != nil && !errors.Is(errors.Cause(err), errs.MetaNotFound) {
		return false
	}

	return common.CanAccess(user, meta, reqPath, "")
}

