// ExportMediaDB 导出媒体数据
// query: media_type（可选，为空表示全部类型）, scan_path_id（可选，单路径导出）
// 返回 JSON 文件下载流
func ExportMediaDB(c *gin.Context) {
	mediaType := model.MediaType(c.Query("media_type"))
	scanPathIDStr := c.Query("scan_path_id")

	export := MediaExportData{
		Version:	mediaExportVersion,
		ExportAt:	time.Now(),
	}

	if scanPathIDStr != "" {

		id, err := strconv.ParseUint(scanPathIDStr, 10, 64)
		if err != nil {
			common.ErrorStrResp(c, "无效的 scan_path_id", 400)
			return
		}
		sp, err := db.GetMediaScanPath(uint(id))
		if err != nil {
			common.ErrorResp(c, err, 404)
			return
		}
		items, err := db.ListMediaItemsByScanPath(uint(id))
		if err != nil {
			common.ErrorResp(c, err, 500)
			return
		}
		export.Scope = "scan_path"
		export.MediaType = sp.MediaType
		export.ScanPaths = []model.MediaScanPath{*sp}
		export.Items = items
	} else if mediaType != "" {

		paths, err := db.ListMediaScanPaths(mediaType)
		if err != nil {
			common.ErrorResp(c, err, 500)
			return
		}
		items, err := db.ListAllMediaItems(mediaType)
		if err != nil {
			common.ErrorResp(c, err, 500)
			return
		}
		export.Scope = "media_type"
		export.MediaType = mediaType
		export.ScanPaths = paths
		export.Items = items
	} else {

		paths, err := db.ListAllMediaScanPaths()
		if err != nil {
			common.ErrorResp(c, err, 500)
			return
		}
		items, err := db.ListAllMediaItems("")
		if err != nil {
			common.ErrorResp(c, err, 500)
			return
		}
		export.Scope = "all"
		export.ScanPaths = paths
		export.Items = items
	}

	filename := buildExportFilename(export)
	c.Header("Content-Disposition", `attachment; filename="`+filename+`"`)
	c.Header("Content-Type", "application/zip")
	if err := writeMediaExportZip(c.Request.Context(), c.Writer, &export); err != nil {
		log.Errorf("导出媒体数据失败: %v", err)
	}
}

func FinishAuthnLogin(c *gin.Context) {
	enabled := setting.GetBool(conf.WebauthnLoginEnabled)
	if !enabled {
		common.ErrorStrResp(c, "WebAuthn is not enabled", 403)
		return
	}
	authnInstance, err := authn.NewAuthnInstance(c)
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	sessionDataString := c.GetHeader("session")
	sessionDataBytes, err := base64.StdEncoding.DecodeString(sessionDataString)
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	var sessionData webauthn.SessionData
	if err := json.Unmarshal(sessionDataBytes, &sessionData); err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	var user *model.User
	if username := c.Query("username"); username != "" {
		user, err = db.GetUserByName(username)
		if err != nil {
			common.ErrorResp(c, err, 400)
			return
		}
		_, err = authnInstance.FinishLogin(user, sessionData, c.Request)
	} else {
		_, err = authnInstance.FinishDiscoverableLogin(func(_, userHandle []byte) (webauthn.User, error) {

			userID := uint(binary.LittleEndian.Uint64(userHandle))
			user, err = db.GetUserById(userID)
			if err != nil {
				return nil, err
			}

			return user, nil
		}, sessionData, c.Request)
	}
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	token, err := common.GenerateToken(user)
	if err != nil {
		common.ErrorResp(c, err, 400, true)
		return
	}
	common.SuccessResp(c, gin.H{"token": token})
}

