func FsForm(c *gin.Context) {
	defer func() {
		if n, _ := io.ReadFull(c.Request.Body, []byte{0}); n == 1 {
			_, _ = utils.CopyWithBuffer(io.Discard, c.Request.Body)
		}
		_ = c.Request.Body.Close()
	}()
	path := c.GetHeader("File-Path")
	path, err := url.PathUnescape(path)
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}
	asTask := c.GetHeader("As-Task") == "true"
	overwrite := c.GetHeader("Overwrite") != "false"
	user := c.Request.Context().Value(conf.UserKey).(*model.User)
	path, err = user.JoinPath(path)
	if err != nil {
		common.ErrorResp(c, err, 403)
		return
	}
	if !overwrite {
		if res, _ := fs.Get(c.Request.Context(), path, &fs.GetArgs{NoLog: true}); res != nil {
			common.ErrorStrResp(c, "file exists", 403)
			return
		}
	}
	storage, err := fs.GetStorage(path, &fs.GetStoragesArgs{})
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}
	if storage.Config().NoUpload {
		common.ErrorStrResp(c, "Current storage doesn't support upload", 405)
		return
	}
	file, err := c.FormFile("file")
	if err != nil {
		common.ErrorResp(c, err, 500)
		return
	}
	f, err := file.Open()
	if err != nil {
		common.ErrorResp(c, err, 500)
		return
	}
	defer f.Close()
	dir, name := stdpath.Split(path)

	if shouldIgnoreSystemFile(name) {
		common.ErrorStrResp(c, errs.IgnoredSystemFile.Error(), 403)
		return
	}
	h := make(map[*utils.HashType]string)
	if md5 := c.GetHeader("X-File-Md5"); md5 != "" {
		h[utils.MD5] = md5
	}
	if sha1 := c.GetHeader("X-File-Sha1"); sha1 != "" {
		h[utils.SHA1] = sha1
	}
	if sha256 := c.GetHeader("X-File-Sha256"); sha256 != "" {
		h[utils.SHA256] = sha256
	}
	mimetype := file.Header.Get("Content-Type")
	if len(mimetype) == 0 {
		mimetype = utils.GetMimeType(name)
	}
	generateSeed := shouldGenerateUploadSeed(c, dir)
	if generateSeed {
		if err = validateUploadSeedRequest(c); err != nil {
			common.ErrorStrResp(c, err.Error(), 400)
			return
		}
	}
	if generateSeed && asTask {
		common.ErrorStrResp(c, "seed sidecar generation requires synchronous upload", 400)
		return
	}
	var seedHasher *torrent.HashWriter
	var uploadReader io.Reader = f
	if generateSeed {
		sliceSize := uploadSeedSliceSize(c, file.Size)
		seedHasher = torrent.NewHashWriter(sliceSize, sliceSize, 0)
		uploadReader = io.TeeReader(f, seedHasher)
	}
	s := &stream.FileStream{
		Obj: &model.Object{
			Name:		name,
			Size:		file.Size,
			Modified:	getLastModified(c),
			HashInfo:	utils.NewHashInfoByMap(h),
		},
		Reader:		uploadReader,
		Mimetype:	mimetype,
		WebPutAsTask:	asTask,
	}
	var t task.TaskExtensionInfo
	if asTask {
		s.Reader = struct {
			io.Reader
		}{f}
		t, err = fs.PutAsTask(c.Request.Context(), dir, s)
	} else {
		err = fs.PutDirectly(c.Request.Context(), dir, s)
	}
	if err != nil {
		common.ErrorResp(c, err, 500)
		return
	}
	if generateSeed {
		if err = writeUploadSeedSidecar(c, dir, name, file.Size, seedHasher); err != nil {
			common.ErrorResp(c, err, 500)
			return
		}
	}
	if t == nil {
		common.SuccessResp(c)
		return
	}
	common.SuccessResp(c, gin.H{
		"task": getTaskInfo(t),
	})
}

func FsGet(c *gin.Context, req *FsGetReq, user *model.User) {
	reqPath, err := user.JoinPath(req.Path)
	if err != nil {
		common.ErrorResp(c, err, 403)
		return
	}
	meta, err := op.GetNearestMeta(reqPath)
	if err != nil && !errors.Is(errors.Cause(err), errs.MetaNotFound) {
		common.ErrorResp(c, err, 500, true)
		return
	}
	common.GinAppendValues(c, conf.MetaKey, meta)
	if !common.CanAccess(user, meta, reqPath, req.Password) {
		common.ErrorStrResp(c, "password is incorrect or you have no permission", 403)
		return
	}
	obj, err := fs.Get(c.Request.Context(), reqPath, &fs.GetArgs{
		WithStorageDetails: !user.IsGuest() && !setting.GetBool(conf.HideStorageDetails),
	})
	if err != nil {
		common.ErrorResp(c, err, 500)
		return
	}
	var rawURL string

	storage, err := fs.GetStorage(reqPath, &fs.GetStoragesArgs{})
	provider, ok := model.GetProvider(obj)
	if !ok && err == nil {
		provider = storage.Config().Name
	}
	if !obj.IsDir() {
		if err != nil {
			common.ErrorResp(c, err, 500)
			return
		}
		if storage.Config().MustProxy() || storage.GetStorage().WebProxy {
			rawURL = common.GenerateDownProxyURL(storage.GetStorage(), reqPath)
			if rawURL == "" {
				query := ""
				if isEncrypt(meta, reqPath) || setting.GetBool(conf.SignAll) {
					query = "?sign=" + sign.Sign(reqPath)
				}
				rawURL = fmt.Sprintf("%s/p%s%s",
					common.GetApiUrl(c),
					utils.EncodePath(reqPath, true),
					query)
			}
		} else {

			if url, ok := model.GetUrl(obj); ok {
				rawURL = url
			} else {

				link, _, err := fs.Link(c.Request.Context(), reqPath, model.LinkArgs{
					IP:		c.ClientIP(),
					Header:		c.Request.Header,
					Redirect:	true,
				})
				if err != nil {
					common.ErrorResp(c, err, 500)
					return
				}
				defer link.Close()
				rawURL = link.URL
			}
		}
	}
	parentPath := stdpath.Dir(reqPath)
	var related []model.Obj
	if !obj.IsDir() && utils.GetFileType(obj.GetName()) == conf.VIDEO {
		sameLevelFiles, err := fs.List(c.Request.Context(), parentPath, &fs.ListArgs{})
		if err == nil {
			related = filterRelated(sameLevelFiles, obj)
		}
	}
	parentMeta, _ := op.GetNearestMeta(parentPath)
	thumb, _ := model.GetThumb(obj)
	mountDetails, _ := model.GetStorageDetails(obj)
	common.SuccessResp(c, FsGetResp{
		ObjResp: ObjResp{
			Name:		obj.GetName(),
			Size:		obj.GetSize(),
			IsDir:		obj.IsDir(),
			Modified:	obj.ModTime(),
			Created:	obj.CreateTime(),
			HashInfoStr:	obj.GetHash().String(),
			HashInfo:	obj.GetHash().Export(),
			Sign:		common.Sign(obj, parentPath, isEncrypt(meta, reqPath)),
			Type:		utils.GetObjType(obj.GetName(), obj.IsDir()),
			Thumb:		thumb,
			MountDetails:	mountDetails,
		},
		RawURL:		rawURL,
		Readme:		getReadme(meta, reqPath),
		Header:		getHeader(meta, reqPath),
		Provider:	provider,
		Related:	toObjsResp(related, parentPath, isEncrypt(parentMeta, parentPath)),
	})
}

// FsGetDirectUploadInfo returns the direct upload info if supported by the driver
// If the driver does not support direct upload, returns null for upload_info
func FsGetDirectUploadInfo(c *gin.Context) {
	var req FsGetDirectUploadInfoReq
	if err := c.ShouldBind(&req); err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	path, err := url.PathUnescape(req.Path)
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	user := c.Request.Context().Value(conf.UserKey).(*model.User)
	path, err = user.JoinPath(path)
	if err != nil {
		common.ErrorResp(c, err, 403)
		return
	}
	if err := checkRelativePath(req.FileName); err != nil {
		common.ErrorResp(c, err, 403)
		return
	}

	dstPath := stdpath.Join(path, req.FileName)
	path = stdpath.Dir(dstPath)
	req.FileName = stdpath.Base(dstPath)
	parentMeta, err := op.GetNearestMeta(path)
	if err != nil && !errors.Is(errors.Cause(err), errs.MetaNotFound) {
		common.ErrorResp(c, err, 500, true)
		return
	}
	if !user.CanWriteContent() && !common.CanWriteContentBypassUserPerms(parentMeta, path) {
		common.ErrorResp(c, errs.PermissionDenied, 403)
		return
	}
	if !common.CanWrite(user, parentMeta, path) {
		common.ErrorResp(c, errs.PermissionDenied, 403)
		return
	}

	parentMountPath, err := op.GetStorageVirtualMountPath(path)
	if err != nil {
		common.ErrorResp(c, err, 500)
		return
	}
	targetMountPath, err := op.GetStorageVirtualMountPath(dstPath)
	if err != nil {
		common.ErrorResp(c, err, 500)
		return
	}
	if parentMountPath != targetMountPath {
		common.ErrorResp(c, errs.PermissionDenied, 403)
		return
	}
	overwrite := c.GetHeader("Overwrite") != "false"
	if !overwrite {
		res, err := fs.Get(c.Request.Context(), dstPath, &fs.GetArgs{NoLog: true})
		if err != nil && !errs.IsObjectNotFound(err) {
			common.ErrorResp(c, err, 500)
			return
		}
		if res != nil {
			common.ErrorStrResp(c, "file exists", 403)
			return
		}
	}
	if req.ContentType != "" {
		if _, _, err := mime.ParseMediaType(req.ContentType); err != nil {
			common.ErrorResp(c, err, 400)
			return
		}
	}
	ctx := context.WithValue(c, conf.DirectUploadContentTypeKey, req.ContentType)
	directUploadInfo, err := fs.GetDirectUploadInfo(ctx, req.Tool, path, req.FileName, req.FileSize, overwrite)
	if err != nil {
		if !overwrite && errs.IsObjectAlreadyExists(err) {
			common.ErrorStrResp(c, "file exists", 403)
			return
		}
		common.ErrorResp(c, err, 500)
		return
	}
	common.SuccessResp(c, directUploadInfo)
}

