// ImportMediaDB 导入媒体数据
// 支持两种调用方式：
//  1. multipart/form-data：file 字段携带导出生成的 JSON 文件
//  2. application/json：直接 POST 整个 MediaExportData 结构
//
// 可选 query 参数 scan_path_id：当导入"scan_path"范围数据时，
// 把所有条目重定向到该扫描路径ID（覆盖文件中原有的 scan_path_id）。
func ImportMediaDB(c *gin.Context) {
	parsed, covers, err := readMediaImportRequest(c, maxImportBytes)
	if err != nil {
		status := http.StatusBadRequest
		var sizeErr *http.MaxBytesError
		if errors.As(err, &sizeErr) {
			status = http.StatusRequestEntityTooLarge
		}
		common.ErrorResp(c, err, status)
		return
	}
	data := *parsed
	complete := false
	defer func() {
		if !complete {
			cleanupMediaImportedCovers(covers)
		}
	}()

	if data.Version <= 0 || data.Version > mediaExportVersion {
		common.ErrorStrResp(c, "不支持的导入文件版本", 400)
		return
	}

	idMap, spCreated, spUpdated, err := db.ImportMediaScanPaths(data.ScanPaths)
	if err != nil {
		common.ErrorResp(c, err, 500)
		return
	}

	scanPathIDStr := c.Query("scan_path_id")
	var override *uint
	if scanPathIDStr != "" {
		if id, err := strconv.ParseUint(scanPathIDStr, 10, 64); err == nil {
			v := uint(id)
			override = &v
		}
	}
	if override == nil {
		for i := range data.Items {
			if newID, ok := idMap[data.Items[i].ScanPathID]; ok {
				data.Items[i].ScanPathID = newID
			}
		}
	}

	itemCreated, itemUpdated, err := db.ImportMediaItems(data.Items, override)
	if err != nil {
		common.ErrorResp(c, err, 500)
		return
	}

	complete = true
	cleanupMediaImportedCovers(covers)
	common.SuccessResp(c, gin.H{
		"scan_paths_created":	spCreated,
		"scan_paths_updated":	spUpdated,
		"items_created":	itemCreated,
		"items_updated":	itemUpdated,
	})
}

// InitSetup 执行系统初始化：创建管理员账号并设置站点名称等初始参数。
// 仅在系统尚未初始化时允许调用；已初始化则返回错误。
func InitSetup(c *gin.Context) {
	var req InitSetupReq
	if err := c.ShouldBind(&req); err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	if _, err := op.GetAdmin(); err == nil {
		common.ErrorStrResp(c, "system has already been initialized", 400)
		return
	} else if !errors.Is(err, gorm.ErrRecordNotFound) {
		common.ErrorResp(c, err, 500, true)
		return
	}

	if len(req.Password) < 4 {
		common.ErrorStrResp(c, "password must be at least 4 characters", 400)
		return
	}
	admin := &model.User{
		Username:	req.Username,
		Role:		model.ADMIN,
		BasePath:	"/",
		Authn:		"[]",
		Permission:	0x71FF,
	}
	admin.SetPassword(req.Password)
	if err := op.CreateUser(admin); err != nil {
		common.ErrorResp(c, err, 500, true)
		return
	}

	if req.SiteTitle != "" {
		item := model.SettingItem{
			Key:	conf.SiteTitle,
			Value:	req.SiteTitle,
			Type:	conf.TypeString,
			Group:	model.SITE,
			Flag:	model.PUBLIC,
		}
		if err := op.SaveSettingItem(&item); err != nil {
			common.ErrorResp(c, err, 500, true)
			return
		}
	}
	common.SuccessResp(c)
}

// InitStatus 返回系统是否已完成初始化（即是否已存在管理员账号）。
// 前端据此判断是否跳转到安装向导。
func InitStatus(c *gin.Context) {
	if _, err := op.GetAdmin(); err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			common.SuccessResp(c, gin.H{"initialized": false})
			return
		}
		common.ErrorResp(c, err, 500, true)
		return
	}
	common.SuccessResp(c, gin.H{"initialized": true})
}

