		return
	}
	size, err := strconv.ParseInt(c.Query("size"), 10, 64)
	if err != nil {
		common.ErrorStrResp(c, "status lookup requires upload_id, or path and size", 400)
		return
	}
	snap, err := multipart.DefaultManager.Find(user, path, size)
	if err != nil {
		common.ErrorResp(c, err, multipartErrCode(err))
		return
	}
	common.SuccessResp(c, snap)
}

func OIDCLoginCallback(c *gin.Context) {
	useCompatibility := setting.GetBool(conf.SSOCompatibilityMode)
	method := c.Query("method")
	if useCompatibility {
		method = path.Base(c.Request.URL.Path)
	}
	clientId := setting.GetStr(conf.SSOClientId)
	endpoint := setting.GetStr(conf.SSOEndpointName)
	provider, err := oidc.NewProvider(c, endpoint)
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}
	oauth2Config, err := GetOIDCClient(c, useCompatibility, "", method)
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}
	if method == "get_sso_id" {
		if _, err := parseSSOBindingToken(c, c.Query("state"), ssoBindingStatePurpose); err != nil {
			common.ErrorStrResp(c, "incorrect or expired state parameter", 400)
			return
		}
	} else if !verifyState(clientId, c.ClientIP(), c.Query("state")) {
		common.ErrorStrResp(c, "incorrect or expired state parameter", 400)
		return
	}
	oauth2Token, err := oauth2Config.Exchange(c, c.Query("code"))
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}
	rawIDToken, ok := oauth2Token.Extra("id_token").(string)
	if !ok {
		common.ErrorStrResp(c, "no id_token found in oauth2 token", 400)
		return
	}
	verifier := provider.Verifier(&oidc.Config{
		ClientID: clientId,
	})
	_, err = verifier.Verify(c, rawIDToken)
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}
	payload, err := parseJWT(rawIDToken)
	if err != nil {
		common.ErrorResp(c, err, 400)
		return
	}
	userID := utils.Json.Get(payload, setting.GetStr(conf.SSOOIDCUsernameKey, "name")).ToString()
	if userID == "" {
		common.ErrorStrResp(c, "cannot get username from OIDC provider", 400)
		return
	}
	if method == "get_sso_id" {
		bindingProof, err := generateSSOBindingToken(c, ssoBindingProofPurpose, userID)
		if err != nil {
			common.ErrorResp(c, err, 500)
			return
		}
		if useCompatibility {
			c.Redirect(302, common.GetApiUrl(c)+"/@manage?sso_id="+bindingProof)
			return
		}
		ssoPostMessage(c, map[string]string{"sso_id": bindingProof})
		return
	}
	if method == "sso_get_token" {
		user, err := db.GetUserBySSOID(userID)
		if err != nil {
			user, err = autoRegister(userID, userID, err)
			if err != nil {
				common.ErrorResp(c, err, 400)
				return
			}
		}
		token, err := common.GenerateToken(user)
		if err != nil {
			common.ErrorResp(c, err, 400)
			return
		}
		if useCompatibility {
			c.Redirect(302, common.GetApiUrl(c)+"/@login?token="+token)
			return
		}
		ssoPostMessage(c, map[string]string{"token": token})
		return
	}
}

