// TorrentRapidUpload 从 torrent 文件中提取 CAS 信息尝试秒传到天翼云
func TorrentRapidUpload(c *gin.Context) {
	user := c.Request.Context().Value(conf.UserKey).(*model.User)

	var req TorrentRapidUploadReq
	if err := c.ShouldBind(&req); err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	reqPath, err := user.JoinPath(req.Path)
	if err != nil {
		common.ErrorResp(c, err, 403)
		return
	}

	meta, err := op.GetNearestMeta(reqPath)
	if err != nil && !errors.Is(errors.Cause(err), errs.MetaNotFound) {
		common.ErrorResp(c, err, 500, true)
		return
	}
	if (!user.CanWriteContent() && !common.CanWriteContentBypassUserPerms(meta, reqPath)) || !common.CanWrite(user, meta, reqPath) {
		common.ErrorResp(c, errs.PermissionDenied, 403)
		return
	}
	if len(req.TorrentData) > maxTorrentBase64Len {
		common.ErrorStrResp(c, "torrent data exceeds the maximum size", 413)
		return
	}

	torrentData, err := base64.StdEncoding.DecodeString(req.TorrentData)
	if err != nil {
		common.ErrorResp(c, fmt.Errorf("invalid base64 data: %w", err), 400)
		return
	}

	t, err := torrent.Decode(torrentData)
	if err != nil {
		common.ErrorResp(c, fmt.Errorf("failed to parse torrent: %w", err), 400)
		return
	}

	if !t.HasCASInfo() {
		common.ErrorResp(c, fmt.Errorf("torrent has no CAS metadata, rapid upload is not possible"), 400)
		return
	}

	storage, dstDirActualPath, err := op.GetStorageAndActualPath(reqPath)
	if err != nil {
		common.ErrorResp(c, err, 500)
		return
	}

	dstDir, err := op.Get(c.Request.Context(), storage, dstDirActualPath)
	if err != nil {
		common.ErrorResp(c, fmt.Errorf("failed to get the destination folder: %w", err), 500)
		return
	}
	if !dstDir.IsDir() {
		common.ErrorResp(c, errs.NotFolder, 400)
		return
	}

	rapid, ok := storage.(driver.SeedRapidUploader)
	if !ok {
		common.ErrorResp(c, fmt.Errorf("target driver %s does not support hash-based rapid upload (CAS)", storage.GetStorage().Driver), 400)
		return
	}

	rapidReq := buildSeedRapidUploadRequest(t, nil)
	if rapidReq == nil {
		common.ErrorResp(c, fmt.Errorf("this seed cannot be used for rapid upload: only a single file whose size matches its hashes is supported"), 400)
		return
	}

	progress := fs.NewSeedSaveTask(c.Request.Context(), user, "rapid upload "+rapidReq.Name)
	progress.Report(0, 1, rapidReq.Name, "rapid uploading")
	obj, err := rapid.RapidUploadByHashes(progress.Ctx(), dstDir, rapidReq, true)
	if cancelErr := progress.Ctx().Err(); cancelErr != nil {
		err = cancelErr
	}
	if err != nil {
		progress.Finish(err)
		common.ErrorResp(c, fmt.Errorf("rapid upload failed: %w", err), 400)
		return
	}
	progress.Report(1, 1, obj.GetName(), "rapid upload done")
	progress.Finish(nil)

	common.SuccessResp(c, gin.H{
		"message":	"rapid upload succeeded",
		"file_name":	obj.GetName(),
		"file_size":	obj.GetSize(),
	})
}

// TranscodePlay 入口：POST /api/fs/transcode  body: {path}
//
// 行为：
//  1. 检查 transcode_enabled
//  2. fs.Get 获取文件并跑 Decide
//  3. 不需要转码 → 返回 {transcode:false, direct: true}
//  4. 需要转码 → 创建 Job 入队，返回 {transcode:true, job_id, master_url}
func TranscodePlay(c *gin.Context) {
	if !transcode.IsEnabled() {
		common.SuccessResp(c, gin.H{"transcode": false, "reason": "disabled"})
		return
	}
	var req struct {
		Path string `json:"path" binding:"required"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		common.ErrorResp(c, err, 400)
		return
	}

	user := mediaUser(c)
	if user == nil || (user.IsGuest() && user.Disabled) {
		common.ErrorStrResp(c, "Guest user is disabled, login please", 401)
		return
	}
	if !CanUserAccessPath(user, req.Path) {
		common.ErrorStrResp(c, "path is not accessible", 403)
		return
	}
	obj, err := fs.Get(c.Request.Context(), req.Path, &fs.GetArgs{NoLog: true})
	if err != nil {
		common.ErrorResp(c, err, 500)
		return
	}
	if obj.IsDir() {
		common.ErrorStrResp(c, "path is a directory", 400)
		return
	}
	dec := transcode.Decide(transcode.DecideRequest{
		FileName:	obj.GetName(),
		FileSize:	obj.GetSize(),
	})
	if !dec.NeedTranscode {
		common.SuccessResp(c, gin.H{
			"transcode":	false,
			"reason":	dec.Reason,
		})
		return
	}

	mgr := transcode.Default()
	mgr.Start()

	apiURL := common.GetApiUrlFromRequest(c.Request)

	ownerID := "user:" + strconv.FormatUint(uint64(user.ID), 10)
	if user.IsGuest() {
		ownerID = "guest:" + c.ClientIP()
	}

	if exist, ok := mgr.Scheduler.FindReusable(ownerID, req.Path); ok {
		respondTranscodeJob(c, apiURL, exist)
		return
	}

	// 【内存优化】优先尝试解析为本地文件路径，让 ffmpeg 直接读取本地文件，
	// 完全绕过 HTTP /d 代理路径——避免 net.Downloader 给每个 range 请求分配
	// 高达 MaxBufferLimit (默认系统内存 5%) 的大缓冲。这是降低 Go 进程内存
	// 占用最有效的方法。如果不是本地驱动则退回到 HTTP 签名 URL。
	var sourceURL string
	if localFile, ok := resolveLocalFilePath(req.Path); ok {

		sourceURL = localFile
		fmt.Printf("[transcode] using local file path for ffmpeg: %s\n", localFile)
	} else {

		base := trustedInternalBaseURL()
		if base == "" {

			common.ErrorStrResp(
				c,
				"transcode needs site_url (or an HTTP port) to fetch the source",
				503,
			)
			return
		}
		signedPath := sign.Sign(req.Path)
		sourceURL = fmt.Sprintf("%s/d%s?sign=%s", base, encodePath(req.Path), signedPath)
	}
	if !transcode.ValidSourceInput(sourceURL) {
		common.ErrorStrResp(c, "unsupported transcode source", 400)
		return
	}

	job := transcode.NewJob()
	job.Path = req.Path
	job.OwnerID = ownerID
	job.SourceURL = sourceURL

	if err := mgr.Scheduler.Capacity(ownerID); err != nil {
		common.ErrorResp(c, err, 429)
		return
	}
	if !probeSlots.acquire(ownerID) {
		common.ErrorStrResp(c, "too many concurrent transcode requests", 429)
		return
	}

	probe, perr := func() (transcode.SourceProbe, error) {

		defer probeSlots.release(ownerID)
		return transcode.ProbeSource(sourceURL)
	}()
	if perr != nil {

		fmt.Printf("[transcode] probe source failed: %v\n", perr)
		probe = transcode.SourceProbe{Size: obj.GetSize()}
	} else if probe.Size == 0 {
		probe.Size = obj.GetSize()
	}
	job.Probe = probe
	profile := transcode.BuildProfile()
	job.Profiles = []transcode.Profile{profile}
	job.Output = transcode.BuildOutputSpec()
	timeoutMin := setting.GetInt(conf.TranscodeJobTimeoutMin, 120)
	job.Deadline = time.Now().Add(time.Duration(timeoutMin) * time.Minute).Unix()
	submitted, _, err := mgr.Scheduler.SubmitLimited(job)
	if err != nil {

		common.ErrorResp(c, err, 429)
		return
	}
	respondTranscodeJob(c, apiURL, submitted)
}

func UpdateCurrent(c *gin.Context) {
	var req model.User
	if err := c.ShouldBind(&req); err != nil {
		common.ErrorResp(c, err, 400)
		return
	}
	user := c.Request.Context().Value(conf.UserKey).(*model.User)
	if user.IsGuest() {
		common.ErrorStrResp(c, model.GuestCannotUpdateProfile, 403)
		return
	}
	ssoID := req.SsoID
	if req.SsoID != "" && req.SsoID != user.SsoID {
		claims, err := parseSSOBindingToken(c, req.SsoID, ssoBindingProofPurpose)
		if err != nil {
			common.ErrorStrResp(c, "invalid or expired SSO binding proof", 400)
			return
		}
		boundUser, err := db.GetUserBySSOID(claims.SsoID)
		if err == nil && boundUser.ID != user.ID {
			common.ErrorStrResp(c, "SSO account is already bound to another user", 409)
			return
		}
		if err != nil && !errors.Is(err, gorm.ErrRecordNotFound) {
			common.ErrorResp(c, err, 500)
			return
		}
		ssoID = claims.SsoID
	}
	user.Username = req.Username
	if req.Password != "" {
		user.SetPassword(req.Password)
	}
	user.SsoID = ssoID
	if err := op.UpdateUser(user); err != nil {
		common.ErrorResp(c, err, 500)
	} else {
		common.SuccessResp(c)
	}
}

func UpdateIndex(c *gin.Context) {
	var req UpdateIndexReq
	if err := c.ShouldBind(&req); err != nil {
		common.ErrorResp(c, err, 400)
		return
	}
	if search.Running() {
		common.ErrorStrResp(c, "index is running", 400)
		return
	}
	if !search.Config(c).AutoUpdate {
		common.ErrorStrResp(c, "update is not supported for current index", 400)
		return
	}
	go func() {
		ctx := context.Background()
		progress, err := search.Progress()
		if err != nil {
			log.Errorf("get index progress error: %+v", err)
			progress = &model.IndexProgress{}
		}
		for _, path := range req.Paths {
			err = search.Del(ctx, path)
			if err != nil {
				log.Errorf("delete index on %s error: %+v", path, err)
				return
			}
		}
		err = search.BuildIndex(context.Background(), req.Paths,
			conf.SlicesMap[conf.IgnorePaths], req.MaxDepth, false)
		if err != nil {
			log.Errorf("update index error: %+v", err)
			now := time.Now()
			search.WriteProgress(&model.IndexProgress{
				ObjCount:	progress.ObjCount,
				IsDone:		true,
				LastDoneTime:	&now,
				Error:		err.Error(),
			})
			return
		}
		now := time.Now()
		search.WriteProgress(&model.IndexProgress{
			ObjCount:	progress.ObjCount,
			IsDone:		true,
			LastDoneTime:	&now,
			Error:		"",
		})
	}()
	common.SuccessResp(c)
}

// UpdateMediaAlbumAdmin 按专辑批量更新
//
//	POST /api/admin/media/album/update
func UpdateMediaAlbumAdmin(c *gin.Context) {
	var req UpdateMediaAlbumReq
	if err := c.ShouldBindJSON(&req); err != nil {
		common.ErrorResp(c, err, 400)
		return
	}
	if req.AlbumName == nil && req.AlbumArtist == nil {
		common.ErrorStrResp(c, "缺少专辑定位字段", 400)
		return
	}
	albumName, albumArtist := "", ""
	if req.AlbumName != nil {
		albumName = *req.AlbumName
	}
	if req.AlbumArtist != nil {
		albumArtist = *req.AlbumArtist
	}
	items, err := db.ListMediaItemsByAlbum(albumName, albumArtist, req.ScanPathID)
	if err != nil {
		common.ErrorResp(c, err, 500)
		return
	}
	if len(items) == 0 {
		common.ErrorStrResp(c, "专辑下没有曲目", 404)
		return
	}

	if req.Cover != nil && len(*req.Cover) > maxCoverFieldLen {
		common.ErrorStrResp(c, "封面数据过大（上限 12MB）", 400)
		return
	}

	oldCovers := make([]string, 0, len(items))
	for i := range items {
		item := &items[i]
		if req.NewAlbumName != nil {
			item.AlbumName = *req.NewAlbumName

			if item.IsFolder && item.ScrapedName != "" {
				item.ScrapedName = *req.NewAlbumName
			}
		}
		if req.NewAlbumArtist != nil {
			item.AlbumArtist = *req.NewAlbumArtist
		}
		if req.Cover != nil {
			if item.Cover != *req.Cover {
				oldCovers = append(oldCovers, item.Cover)
			}
			item.Cover = *req.Cover
		}
		if req.ReleaseDate != nil {
			item.ReleaseDate = *req.ReleaseDate
		}
		if req.Genre != nil {
			item.Genre = *req.Genre
		}
		if req.Plot != nil {
			item.Plot = *req.Plot
		}
		if req.Description != nil {
			item.Description = *req.Description
		}
	}
	if err := db.UpdateMediaItems(items); err != nil {
		common.ErrorResp(c, err, 500)
		return
	}
	for _, old := range oldCovers {
		removeUploadedCover(old, "")
	}
	common.SuccessResp(c, gin.H{"affected": len(items)})
}

