// buildExportFilename 根据导出范围生成下载文件名
func buildExportFilename(d MediaExportData) string {
	ts := d.ExportAt.Format("20060102_150405")
	switch d.Scope {
	case "scan_path":
		spName := ""
		if len(d.ScanPaths) > 0 {
			spName = d.ScanPaths[0].Name
			if spName == "" {
				spName = d.ScanPaths[0].Path
			}
		}

		safe := strings.NewReplacer("/", "_", "\\", "_", ":", "_", "?", "_", "*", "_", "\"", "_", "<", "_", ">", "_", "|", "_").Replace(spName)
		return "media_export_" + string(d.MediaType) + "_" + safe + "_" + ts + ".zip"
	case "media_type":
		return "media_export_" + string(d.MediaType) + "_" + ts + ".zip"
	default:
		return "media_export_all_" + ts + ".zip"
	}
}

// buildSeedFileRapidUploadRequest builds a rapid-upload request for exactly one
// seed file, straight from the seed's hash matrix.
//
// It must not go through a torrent container: EncodeSeed(format="torrent")
// requires SHA-1 piece hashes, which CAS seeds (MD5 + slice MD5s) never carry,
// so the old round trip rejected every 189-style 秒传 before any request was
// sent. Reading the seed file directly also keeps the drive's own slice size
// and legacy slice digest intact.
//
// open lazily provides the file content and may be nil.
func buildSeedFileRapidUploadRequest(seed *torrent.Seed, file torrent.SeedFile, open func() (model.FileStreamer, error)) *driver.SeedRapidUploadRequest {
	if seed == nil || file.Size < 0 {
		return nil
	}
	name := stdpath.Base(file.Path)
	if name == "" || name == "." || name == ".." {
		return nil
	}
	wholeHashes := make(map[*utils.HashType]string)
	if file.Hashes.MD5 != "" {
		wholeHashes[utils.MD5] = strings.ToUpper(file.Hashes.MD5)
	}
	if file.Hashes.SHA1 != "" {
		wholeHashes[utils.SHA1] = strings.ToUpper(file.Hashes.SHA1)
	}
	if file.Hashes.SHA256 != "" {
		wholeHashes[utils.SHA256] = strings.ToUpper(file.Hashes.SHA256)
	}
	if file.Hashes.GCID != "" {
		wholeHashes[hash_extend.GCID] = strings.ToUpper(file.Hashes.GCID)
	}

	sliceSize := seed.PieceSize
	if file.CASCloud == "" || file.CASCloud == torrent.Cloud189 {
		sliceSize = torrent.CASSliceSize(file.Size)
	}
	req := &driver.SeedRapidUploadRequest{
		Name:		name,
		Size:		file.Size,
		SliceSize:	sliceSize,
		SliceMD5:	strings.ToUpper(file.CASSliceMD5),
		Open:		open,
	}
	if file.Hashes.Pieces != nil {
		req.SliceMD5s = file.Hashes.Pieces.MD5
		req.SliceSHA1s = file.Hashes.Pieces.SHA1
	}
	req.Whole = &utils.HashInfo{}
	*req.Whole = utils.NewHashInfoByMap(wholeHashes)
	return req
}

// buildSeedRapidUploadRequest converts a parsed torrent's CAS metadata into a
// driver.SeedRapidUploadRequest. open lazily provides the file content and may
// be nil when no content source is available.
func buildSeedRapidUploadRequest(t *torrent.Torrent, open func() (model.FileStreamer, error)) *driver.SeedRapidUploadRequest {
	if t == nil {
		return nil
	}

	wholeHashes := make(map[*utils.HashType]string)
	req := &driver.SeedRapidUploadRequest{
		Name:	t.Info.Name,
		Size:	t.GetTotalSize(),
		Open:	open,
	}

	if t.CAS != nil {
		req.SliceSize = t.CAS.SliceSize
		req.SliceMD5s = t.CAS.SliceMD5s
		if t.CAS.FileMD5 != "" {
			wholeHashes[utils.MD5] = strings.ToUpper(t.CAS.FileMD5)
		}
	}

	if t.OpenList != nil {
		if len(t.OpenList.Files) > 1 {
			return nil
		}
		if req.SliceSize == 0 {
			req.SliceSize = t.OpenList.PieceSize
		}
		if len(t.OpenList.Files) == 1 {
			sf := t.OpenList.Files[0]
			if sf.Size > 0 && sf.Size != t.GetTotalSize() {
				return nil
			}
			if sf.Hashes.MD5 != "" {
				wholeHashes[utils.MD5] = strings.ToUpper(sf.Hashes.MD5)
			}
			if sf.Hashes.SHA1 != "" {
				wholeHashes[utils.SHA1] = strings.ToUpper(sf.Hashes.SHA1)
			}
			if sf.Hashes.SHA256 != "" {
				wholeHashes[utils.SHA256] = strings.ToUpper(sf.Hashes.SHA256)
			}
			if sf.Hashes.GCID != "" {
				wholeHashes[hash_extend.GCID] = strings.ToUpper(sf.Hashes.GCID)
			}
			if sf.Hashes.Pieces != nil {
				if len(req.SliceMD5s) == 0 && len(sf.Hashes.Pieces.MD5) > 0 {
					req.SliceMD5s = sf.Hashes.Pieces.MD5
				}
				if len(sf.Hashes.Pieces.SHA1) > 0 {
					req.SliceSHA1s = sf.Hashes.Pieces.SHA1
				}
			}
		}
	}

	req.Whole = &utils.HashInfo{}
	*req.Whole = utils.NewHashInfoByMap(wholeHashes)
	return req
}

