// convertSeedToFormat 把 seed 编码成目标格式，缺哈希时按需从文件补算。
func convertSeedToFormat(ctx context.Context, user *model.User, seed *torrent.Seed, target string, req SeedConvertReq) ([]byte, error) {
	matrix := seedConvertMatrix(req.HashMatrix, target)
	missing := matrix != nil && seedConvertMatrixMissing(seed, *matrix)
	if matrix != nil {
		for i := range seed.Files {
			applySeedMatrix(&seed.Files[i], *matrix)
		}
		if !matrix.SHA1.Pieces {
			seed.GlobalPieces = nil
		}
		seed.AvailableHashes = nil
		seed.AvailablePieceHashes = nil
	}
	if !missing && len(torrent.DiagnoseConversion(seed, target)) == 0 {
		return torrent.EncodeSeed(seed, target)
	}
	if !req.ComputeMissing {
		return nil, fmt.Errorf("seed cannot be converted to %s without reading source files", target)
	}
	var pieces []byte
	var err error
	if matrix == nil {
		pieces, err = fs.RehashSeedFromFiles(ctx, user, seed, req.FileBasePath, target)
	} else {
		pieces, err = fs.RehashSeedFromFilesWithMatrix(ctx, user, seed, req.FileBasePath, target, fs.SeedHashMatrix{
			MD5:	fs.SeedHashSelection(matrix.MD5), SHA1: fs.SeedHashSelection(matrix.SHA1), SHA256: fs.SeedHashSelection(matrix.SHA256),
		})
	}
	if err != nil {
		return nil, err
	}
	if target == "torrent" {
		return fs.EncodeGeneratedSeed(seed, "torrent", pieces)
	}
	if remain := torrent.DiagnoseConversion(seed, target); len(remain) > 0 {
		return nil, fmt.Errorf("%s", strings.Join(remain, "; "))
	}
	return torrent.EncodeSeed(seed, target)
}

// coverBytes 读取封面内容（data: / thumb: / http(s)），失败返回 nil。
// 返回的扩展名用于压缩包内的文件名。
func coverBytes(ctx context.Context, cover string) ([]byte, string) {
	cover = strings.TrimSpace(cover)
	if cover == "" || ctx.Err() != nil {
		return nil, ""
	}
	var data []byte
	var err error
	switch {
	case strings.HasPrefix(cover, "data:"):
		idx := strings.Index(cover, ";base64,")
		if idx < 0 {
			return nil, ""
		}
		encoded := cover[idx+len(";base64,"):]
		if len(encoded) > base64.StdEncoding.EncodedLen(maxCoverBytes) {
			return nil, ""
		}
		data, err = base64.StdEncoding.DecodeString(encoded)
	case strings.HasPrefix(cover, "thumb:/"):
		if _, pathErr := mediaExportThumbPath(cover); pathErr != nil {
			return nil, ""
		}
		dir := thumbsDirName()
		root, openErr := os.OpenRoot(scraper.RuntimeThumbRoot(dir))
		if openErr != nil {
			return nil, ""
		}
		defer root.Close()
		name := strings.TrimPrefix(cover, "thumb:/"+dir+"/")
		f, openErr := root.Open(filepath.FromSlash(name))
		if openErr != nil {
			return nil, ""
		}
		defer f.Close()
		stat, statErr := f.Stat()
		if statErr != nil || !stat.Mode().IsRegular() || stat.Size() > maxCoverBytes {
			return nil, ""
		}
		data, err = io.ReadAll(io.LimitReader(f, maxCoverBytes+1))
	case strings.HasPrefix(cover, "http://"), strings.HasPrefix(cover, "https://"):
		u, parseErr := url.Parse(cover)
		if parseErr != nil || safeCoverURL(u) != nil || u.User != nil {
			return nil, ""
		}
		fetchCtx, cancel := context.WithTimeout(ctx, coverFetchTimeout)
		defer cancel()
		resp, fetchErr := fetchCover(fetchCtx, u.String())
		if fetchErr != nil {
			return nil, ""
		}
		defer resp.Body.Close()
		data, err = io.ReadAll(io.LimitReader(resp.Body, maxCoverBytes+1))
	default:
		return nil, ""
	}
	if err != nil || ctx.Err() != nil || len(data) == 0 || len(data) > maxCoverBytes {
		return nil, ""
	}
	ext := rasterCoverExt(data)
	if ext == "" {
		return nil, ""
	}
	return data, ext
}

// coverFileExt 根据文件头判断图片类型，非图片返回空
func coverFileExt(data []byte) string {
	switch http.DetectContentType(data) {
	case "image/jpeg":
		return ".jpg"
	case "image/png":
		return ".png"
	case "image/gif":
		return ".gif"
	case "image/webp":
		return ".webp"
	}
	return ""
}

func dealError(c *gin.Context, err error) bool {
	if err == nil {
		return false
	} else if errors.Is(err, errs.SharingNotFound) {
		common.ErrorStrResp(c, "the share does not exist", 500)
	} else if errors.Is(err, errs.InvalidSharing) {
		common.ErrorStrResp(c, "the share has expired or is no longer valid", 500)
	} else if errors.Is(err, errs.WrongShareCode) {
		common.ErrorResp(c, err, 403)
	} else if errors.Is(err, errs.WrongArchivePassword) {
		common.ErrorResp(c, err, 202)
	} else {
		common.ErrorResp(c, err, 500)
	}
	return true
}

func decodeSeedData(req SeedDataReq) ([]byte, *torrent.Seed, string, error) {
	if strings.TrimSpace(req.SeedData) == "" {
		return nil, nil, "", fmt.Errorf("seed_data is required")
	}
	if len(req.SeedData) > maxTorrentBase64Len {
		return nil, nil, "", fmt.Errorf("seed data is too large")
	}
	data, err := base64.StdEncoding.DecodeString(req.SeedData)
	if err != nil {
		return nil, nil, "", fmt.Errorf("invalid base64 seed data: %w", err)
	}
	format := strings.ToLower(strings.TrimPrefix(req.Format, "."))
	if format == "" {
		format = torrent.DetectFormat(req.FileName, data)
	}
	seed, err := torrent.DecodeSeed(data, format, torrent.DefaultParseLimits())
	if err != nil {
		return nil, nil, "", err
	}
	return data, seed, format, nil
}

