// fetchCover 拉取图片，仅接受 200 且 Content-Type 为 image/*
// 重定向的每一跳都重新做域名校验，避免白名单域名 302 到内网造成 SSRF。
func fetchCover(ctx context.Context, raw string) (*http.Response, error) {
	client := &http.Client{
		Timeout:	20 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= 3 {
				return fmt.Errorf("too many redirects")
			}
			return safeCoverURL(req.URL)
		},
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, raw, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; OpenList-Media/1.0)")
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	if resp.StatusCode != http.StatusOK {
		_ = resp.Body.Close()
		return nil, fmt.Errorf("unexpected status %d", resp.StatusCode)
	}
	return resp, nil
}

// fetchCovers 并发读取封面内容（key 为 items 下标）。
// 单个封面失败只跳过它自己，不影响整次导出；总量超限后不再继续读取。
func fetchCovers(ctx context.Context, items []model.MediaItem) map[int]coverBlob {
	return fetchCoversWithBudget(ctx, items, maxExportCovers, maxExportCoverBytes)
}

func fetchCoversWithBudget(ctx context.Context, items []model.MediaItem, countLimit, byteLimit int) map[int]coverBlob {
	out := make(map[int]coverBlob)
	if countLimit <= 0 || byteLimit <= 0 {
		return out
	}
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	var mu sync.Mutex
	total := 0
	var wg sync.WaitGroup
	sem := make(chan struct{}, coverFetchWorkers)
	count := 0
schedule:
	for i := range items {
		if strings.TrimSpace(items[i].Cover) == "" {
			continue
		}
		if count >= countLimit {
			log.Warnf("导出封面达到数量上限 %d", countLimit)
			break
		}
		select {
		case <-ctx.Done():
			break schedule
		case sem <- struct{}{}:
		}
		mu.Lock()
		stop := ctx.Err() != nil || total >= byteLimit
		mu.Unlock()
		if stop {
			<-sem
			break
		}
		count++
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			defer func() { <-sem }()
			raw, ext := coverBytes(ctx, items[i].Cover)
			if len(raw) == 0 {
				return
			}
			mu.Lock()
			defer mu.Unlock()
			if ctx.Err() != nil {
				return
			}
			if len(raw) > byteLimit-total {
				cancel()
				return
			}
			total += len(raw)
			out[i] = coverBlob{data: raw, ext: ext}
			if total >= byteLimit {
				cancel()
			}
		}(i)
	}
	wg.Wait()
	return out
}

func filterDirs(objs []model.Obj) []DirResp {
	var dirs []DirResp
	for _, obj := range objs {
		if obj.IsDir() {
			dirs = append(dirs, DirResp{
				Name:		obj.GetName(),
				Modified:	obj.ModTime(),
			})
		}
	}
	return dirs
}

func filterRelated(objs []model.Obj, obj model.Obj) []model.Obj {
	var related []model.Obj
	nameWithoutExt := strings.TrimSuffix(obj.GetName(), stdpath.Ext(obj.GetName()))
	for _, o := range objs {
		if o.GetName() == obj.GetName() {
			continue
		}
		if strings.HasPrefix(o.GetName(), nameWithoutExt) {
			related = append(related, o)
		}
	}
	return related
}

func firstUsableSeedSource(file torrent.SeedFile) string {
	if _, err := seedSiteConfig(); err != nil {
		return ""
	}
	for _, source := range file.Sources {
		candidate, parseErr := url.Parse(source.URL)
		if parseErr != nil {
			continue
		}
		if err := validateSeedHost(candidate); err != nil {
			continue
		}
		validPath := (source.Type == "openlist-direct" && strings.HasPrefix(candidate.EscapedPath(), "/d/")) ||
			(source.Type == "openlist-share" && strings.HasPrefix(candidate.EscapedPath(), "/sd/"))
		if !validPath {
			continue
		}
		if source.ExpiresAt != "" {
			expires, parseErr := time.Parse(time.RFC3339, source.ExpiresAt)
			if parseErr != nil || time.Now().After(expires) {
				continue
			}
		}
		return candidate.String()
	}
	return ""
}

func followSeedRemove(c *gin.Context, srcPath string) error {
	for _, sidecarPath := range seedSidecarPaths(srcPath) {
		obj, err := fs.Get(c.Request.Context(), sidecarPath, &fs.GetArgs{NoLog: true})
		if err != nil || obj == nil || obj.IsDir() {
			continue
		}
		if err = fs.Remove(c.Request.Context(), sidecarPath); err != nil {
			return fmt.Errorf("remove seed sidecar %s: %w", sidecarPath, err)
		}
	}
	return nil
}

func followSeedRename(c *gin.Context, srcPath, newName string) error {
	source, err := fs.Get(c.Request.Context(), srcPath, &fs.GetArgs{NoLog: true})
	if err != nil || source == nil || source.IsDir() {
		return nil
	}
	for _, sidecarPath := range seedSidecarPaths(srcPath) {
		obj, err := fs.Get(c.Request.Context(), sidecarPath, &fs.GetArgs{NoLog: true})
		if err != nil || obj == nil || obj.IsDir() {
			continue
		}
		suffix := strings.TrimPrefix(sidecarPath, srcPath)
		if err = fs.Rename(c.Request.Context(), sidecarPath, newName+suffix, true); err != nil {
			return fmt.Errorf("rename seed sidecar %s: %w", sidecarPath, err)
		}
	}
	return nil
}

func followSeedTransfer(c *gin.Context, operation, srcPath, dstDir string) ([]task.TaskExtensionInfo, error) {
	source, err := fs.Get(c.Request.Context(), srcPath, &fs.GetArgs{NoLog: true})
	if err != nil || source == nil || source.IsDir() {
		return nil, nil
	}
	var tasks []task.TaskExtensionInfo
	for _, sidecarPath := range seedSidecarPaths(srcPath) {
		obj, err := fs.Get(c.Request.Context(), sidecarPath, &fs.GetArgs{NoLog: true})
		if err != nil || obj == nil || obj.IsDir() {
			continue
		}
		var current task.TaskExtensionInfo
		switch operation {
		case "copy":
			current, err = fs.Copy(c.Request.Context(), sidecarPath, dstDir, true)
		case "move":
			current, err = fs.Move(c.Request.Context(), sidecarPath, dstDir, true)
		default:
			return nil, fmt.Errorf("unsupported seed sidecar operation %q", operation)
		}
		if err != nil {
			return tasks, fmt.Errorf("%s seed sidecar %s: %w", operation, sidecarPath, err)
		}
		if current != nil {
			tasks = append(tasks, current)
		}
	}
	return tasks, nil
}

func formatAperture(x *exif.Exif) string {
	num, den, ok := exifTagRat(x, exif.FNumber)
	if !ok || num == 0 {
		return ""
	}
	return "f/" + trimFloat(float64(num)/float64(den))
}

// formatExposure 1/250 s、2 s 这种常见写法
func formatExposure(x *exif.Exif) string {
	num, den, ok := exifTagRat(x, exif.ExposureTime)
	if !ok || num == 0 {
		return ""
	}
	if num >= den {
		return trimFloat(float64(num)/float64(den)) + " s"
	}
	return fmt.Sprintf("1/%d s", den/num)
}

func formatFocal(x *exif.Exif) string {
	num, den, ok := exifTagRat(x, exif.FocalLength)
	if !ok || num == 0 {
		return ""
	}
	return trimFloat(float64(num)/float64(den)) + "mm"
}

// formatTakenAt 把 "2019:05:01 12:00:00" 规整成 "2019-05-01 12:00:00"
func formatTakenAt(raw string) string {
	raw = strings.TrimSpace(raw)
	if len(raw) < 19 {
		return raw
	}
	date := strings.ReplaceAll(raw[:10], ":", "-")
	return date + raw[10:19]
}

func generateSSOBindingToken(c *gin.Context, purpose, ssoID string) (string, error) {
	session, err := c.Cookie(ssoBindingCookie)
	expire := ssoBindingExpire
	if purpose == ssoBindingStatePurpose {
		session = random.String(32)
		expire = stateExpire
		c.SetSameSite(http.SameSiteLaxMode)
		c.SetCookie(
			ssoBindingCookie,
			session,
			int((stateExpire + ssoBindingExpire).Seconds()),
			path.Join(conf.URL.Path, "/api"),
			"",
			strings.HasPrefix(common.GetApiUrl(c), "https://"),
			true,
		)
	} else if err != nil {
		return "", errors.New("missing SSO binding session")
	}
	now := time.Now()
	claims := ssoBindingClaims{
		Purpose:	purpose,
		Method:		"get_sso_id",
		SessionDigest:	ssoBindingSessionDigest(session),
		SsoID:		ssoID,
		RegisteredClaims: jwt.RegisteredClaims{
			ExpiresAt:	jwt.NewNumericDate(now.Add(expire)),
			IssuedAt:	jwt.NewNumericDate(now),
			NotBefore:	jwt.NewNumericDate(now),
		},
	}
	return jwt.NewWithClaims(jwt.SigningMethodHS256, claims).SignedString(common.SecretKey)
}

func generateState(clientID, ip string) string {
	state := random.String(stateLength)
	stateCache.Set(_keyState(clientID, state), ip, cache.WithEx[string](stateExpire))
	return state
}

func getBatchHandler[T task.TaskExtensionInfo](manager task.Manager[T], callback func(task T) error) gin.HandlerFunc {
	return func(c *gin.Context) {
		isAdmin, uid, ok := getUserInfo(c)
		if !ok {
			common.ErrorStrResp(c, "user invalid", 401)
			return
		}
		var tids []string
		if err := c.ShouldBind(&tids); err != nil {
			common.ErrorStrResp(c, "invalid request format", 400)
			return
		}
		retErrs := make(map[string]string)
		for _, tid := range tids {
			t, ok := manager.GetByID(tid)
			if !ok || !canAccessTask(t, isAdmin, uid) {
				retErrs[tid] = "task not found"
				continue
			}
			if err := callback(t); err != nil {
				retErrs[tid] = err.Error()
			}
		}
		common.SuccessResp(c, retErrs)
	}
}

func getClearTasksHandler[T task.TaskExtensionInfo](manager task.Manager[T], states ...tache.State) gin.HandlerFunc {
	return func(c *gin.Context) {
		options, err := parseTaskDeleteOptions(c)
		if err != nil {
			common.ErrorResp(c, err, 400)
			return
		}
		isAdmin, uid, ok := getUserInfo(c)
		if !ok {
			common.ErrorStrResp(c, "user invalid", 401)
			return
		}
		tasks := manager.GetByCondition(func(t T) bool {
			return canAccessTask(t, isAdmin, uid) && argsContains(t.GetState(), states...)
		})
		if options.deleteCloudRecord {
			results := make([]taskDeleteResult, 0, len(tasks))
			for _, t := range tasks {
				results = append(results, deleteManagedCloudTask(c, manager, t, options.deleteSourceFile))
			}
			common.SuccessResp(c, gin.H{"results": results})
			return
		}
		var failures []error
		for _, t := range tasks {
			if err := removeManagedTask(manager, t); err != nil {
				failures = append(failures, err)
			}
		}
		if err := errors.Join(failures...); err != nil {
			taskOperationError(c, err)
			return
		}
		common.SuccessResp(c)
