// multipartChunkSize resolves the effective chunk size. The admin setting is
// the ceiling: a client may suggest a smaller chunk via X-Chunk-Size but never
// a larger one — the server buffers a window of several chunks per session, so
// an unbounded client suggestion would translate directly into server-side
// disk usage.
func multipartChunkSize(requested int64) int64 {
	ceiling := int64(setting.GetInt(conf.MultipartChunkSize, 10)) << 20
	if ceiling < multipartMinChunkSize {
		ceiling = multipartMinChunkSize
	}
	size := ceiling
	if requested > 0 && requested < ceiling {
		size = max(requested, multipartMinChunkSize)
	}
	return size
}

func normalizedSeedMatrix(matrix SeedHashMatrix, formats []string) SeedHashMatrix {
	if seedMatrixEmpty(matrix) {
		matrix = loadSeedDefaultMatrix()
	}
	if seedMatrixEmpty(matrix) {
		matrix = SeedHashMatrix{
			MD5:	SeedHashSelection{Whole: true, Pieces: true}, SHA1: SeedHashSelection{Whole: true, Pieces: true},
			SHA256:	SeedHashSelection{Whole: true, Pieces: true},
		}
	}
	for _, format := range formats {
		switch format {
		case "torrent":
			matrix.SHA1 = SeedHashSelection{Whole: true, Pieces: true}
		case "cas":
			matrix.MD5 = SeedHashSelection{Whole: true, Pieces: true}
		}
	}
	return matrix
}

func pagination(objs []model.Obj, req *model.PageReq) (int, []model.Obj) {
	pageIndex, pageSize := req.Page, req.PerPage
	total := len(objs)
	start := (pageIndex - 1) * pageSize
	if start > total {
		return total, []model.Obj{}
	}
	end := start + pageSize
	if end > total {
		end = total
	}
	return total, objs[start:end]
}

func parseJWT(p string) ([]byte, error) {
	parts := strings.Split(p, ".")
	if len(parts) < 2 {
		return nil, fmt.Errorf("oidc: malformed jwt, expected 3 parts got %d", len(parts))
	}
	payload, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return nil, fmt.Errorf("oidc: malformed jwt payload: %v", err)
	}
	return payload, nil
}

func parseSSOBindingToken(c *gin.Context, rawToken, purpose string) (*ssoBindingClaims, error) {
	claims := &ssoBindingClaims{}
	token, err := jwt.ParseWithClaims(rawToken, claims, func(token *jwt.Token) (interface{}, error) {
		if token.Method != jwt.SigningMethodHS256 {
			return nil, errors.New("invalid SSO binding token algorithm")
		}
		return common.SecretKey, nil
	})
	if err != nil || !token.Valid || claims.ExpiresAt == nil || claims.Purpose != purpose ||
		claims.Method != "get_sso_id" || len(claims.SessionDigest) != 43 {
		return nil, errors.New("invalid or expired SSO binding token")
	}
	if (purpose == ssoBindingStatePurpose && claims.SsoID != "") ||
		(purpose == ssoBindingProofPurpose && claims.SsoID == "") {
		return nil, errors.New("invalid SSO binding token payload")
	}
	session, err := c.Cookie(ssoBindingCookie)
	if err != nil || ssoBindingSessionDigest(session) != claims.SessionDigest {
		return nil, errors.New("invalid SSO binding session")
	}
	return claims, nil
}

// An invalid or ambiguous option must not silently fall back to local removal.
func parseTaskDeleteOptions(c *gin.Context) (taskDeleteOptions, error) {
	var options taskDeleteOptions
	query, err := url.ParseQuery(c.Request.URL.RawQuery)
	if err != nil {
		return options, errors.New("invalid task deletion query")
	}
	for _, option := range []struct {
		name	string
		value	*bool
	}{
		{"delete_cloud_record", &options.deleteCloudRecord},
		{"delete_source_file", &options.deleteSourceFile},
	} {
		values, exists := query[option.name]
		if !exists {
			continue
		}
		if len(values) != 1 || (values[0] != "true" && values[0] != "false") {
			return options, errors.New(option.name + " must be a single true or false value")
		}
		*option.value = values[0] == "true"
	}
	if options.deleteSourceFile && !options.deleteCloudRecord {
		return options, errors.New("delete_source_file=true requires delete_cloud_record=true")
	}
	return options, nil
}

