func rasterCoverExt(data []byte) string {
	ext := coverFileExt(data)
	if ext == "" {
		return ""
	}
	cfg, _, err := image.DecodeConfig(bytes.NewReader(data))
	if err != nil || cfg.Width <= 0 || cfg.Height <= 0 ||
		int64(cfg.Width) > maxCoverPixels/int64(cfg.Height) {
		return ""
	}
	if _, _, err := image.Decode(bytes.NewReader(data)); err != nil {
		return ""
	}
	return ext
}

func readMediaExportZipWithBudget(ctx context.Context, r io.ReaderAt, size int64, limits mediaImportLimits) (*MediaExportData, []mediaImportedCover, error) {
	if size < 0 || size > maxImportBytes || ctx.Err() != nil {
		return nil, nil, fmt.Errorf("导入压缩包过大或请求已取消")
	}
	if err := checkMediaZipEntryBudget(ctx, r, size, limits.entries); err != nil {
		return nil, nil, err
	}
	zr, err := zip.NewReader(r, size)
	if err != nil {
		return nil, nil, fmt.Errorf("压缩包解析失败: %w", err)
	}
	if len(zr.File) > limits.entries {
		return nil, nil, fmt.Errorf("压缩包条目数量超限")
	}
	files := make(map[string]*zip.File, len(zr.File))
	for _, f := range zr.File {
		if _, exists := files[f.Name]; exists {
			return nil, nil, fmt.Errorf("压缩包包含重复条目: %s", f.Name)
		}
		files[f.Name] = f
	}
	jsonFile := files[mediaExportJSONName]
	if jsonFile == nil {
		return nil, nil, fmt.Errorf("压缩包里没有 %s", mediaExportJSONName)
	}
	rawJSON, err := readMediaZipEntry(ctx, jsonFile, limits.jsonBytes)
	if err != nil {
		return nil, nil, err
	}
	var data MediaExportData
	if err := json.Unmarshal(rawJSON, &data); err != nil {
		return nil, nil, fmt.Errorf("导入文件解析失败: %w", err)
	}
	if data.Version <= 0 || data.Version > mediaExportVersion {
		return nil, nil, fmt.Errorf("不支持的导入文件版本")
	}
	references := make([]string, 0)
	seen := make(map[string]bool)
	var declaredBytes uint64
	for _, item := range data.Items {
		name := item.Cover
		if !strings.HasPrefix(name, mediaExportCoverDir+"/") || seen[name] {
			continue
		}
		if !safeMediaRelativePath(strings.TrimPrefix(name, mediaExportCoverDir+"/")) {
			return nil, nil, fmt.Errorf("无效的压缩包封面路径")
		}
		f := files[name]
		if f == nil || !f.Mode().IsRegular() {
			return nil, nil, fmt.Errorf("压缩包封面不存在或不是普通文件: %s", name)
		}
		if limits.coverBytes < 0 || f.UncompressedSize64 > maxCoverBytes ||
			f.UncompressedSize64 > uint64(limits.coverBytes)-declaredBytes {
			return nil, nil, fmt.Errorf("导入封面总大小超限")
		}
		declaredBytes += f.UncompressedSize64
		seen[name] = true
		references = append(references, name)
	}
	if len(references) == 0 {
		return &data, nil, nil
	}
	dir := thumbsDirName()
	if !safeMediaRelativePath(dir) {
		return nil, nil, fmt.Errorf("无效的缩略图配置路径")
	}
	root := scraper.RuntimeThumbRoot(dir)
	if err := os.MkdirAll(root, 0o755); err != nil {
		return nil, nil, err
	}
	stage, err := os.MkdirTemp(root, ".media-import-*")
	if err != nil {
		return nil, nil, err
	}
	defer os.RemoveAll(stage)
	saved := make(map[string]string, len(references))
	pending := make([]mediaImportedCover, 0, len(references))
	complete := false
	defer func() {
		if !complete {
			for _, cover := range pending {
				_ = os.Remove(cover.path)
			}
		}
	}()
	var total int64
	for i, name := range references {
		raw, err := readMediaZipEntry(ctx, files[name], min(int64(maxCoverBytes), limits.coverBytes-total))
		if err != nil {
			return nil, nil, err
		}
		ext := rasterCoverExt(raw)
		if ext == "" {
			return nil, nil, fmt.Errorf("压缩包封面不是合法栅格图片: %s", name)
		}
		total += int64(len(raw))
		local := fmt.Sprintf("import-%s-%d%s", strings.TrimPrefix(filepath.Base(stage), ".media-import-"), i, ext)
		if err := os.WriteFile(filepath.Join(stage, local), raw, 0o644); err != nil {
			return nil, nil, err
		}
		cover := "thumb:/" + dir + "/" + local
		saved[name] = cover
		pending = append(pending, mediaImportedCover{filepath.Join(root, local), cover})
	}
	for _, cover := range pending {
		if err := ctx.Err(); err != nil {
			return nil, nil, err
		}
		if err := os.Rename(filepath.Join(stage, filepath.Base(cover.path)), cover.path); err != nil {
			return nil, nil, err
		}
	}
	for i := range data.Items {
		if cover, ok := saved[data.Items[i].Cover]; ok {
			data.Items[i].Cover = cover
		}
	}
	complete = true
	return &data, pending, nil
}

// readMediaHead 读取媒体文件开头最多 limit 字节
func readMediaHead(ctx context.Context, user *model.User, item *model.MediaItem, limit int64) ([]byte, error) {
	fullPath := MediaItemFilePath(item)
	storage, actualPath, err := op.GetStorageAndActualPath(fullPath)
	if err != nil {
		return nil, err
	}
	obj, err := op.Get(ctx, storage, actualPath)
	if err != nil {
		return nil, err
	}
	if obj.IsDir() {
		return nil, fmt.Errorf("not a file: %s", fullPath)
	}
	length := obj.GetSize()
	if length <= 0 || length > limit {
		length = limit
	}
	link, _, err := op.Link(ctx, storage, actualPath, model.LinkArgs{})
	if err != nil {
		return nil, err
	}
	defer link.Close()
	rangeReader, err := stream.GetRangeReaderFromLink(obj.GetSize(), link)
	if err != nil {
		return nil, err
	}
	rc, err := rangeReader.RangeRead(ctx, http_range.Range{Length: length})
	if err != nil {
		return nil, err
	}
	defer rc.Close()

	data, err := io.ReadAll(io.LimitReader(rc, length))
	if err != nil && len(data) == 0 {
		return nil, err
	}
	return data, nil
}

func readMediaImportFile(ctx context.Context, r io.Reader) (*MediaExportData, []mediaImportedCover, error) {
	tmp, err := os.CreateTemp("", "openlist-media-import-*")
	if err != nil {
		return nil, nil, err
	}
	defer func() {
		_ = tmp.Close()
		_ = os.Remove(tmp.Name())
	}()
	size, err := io.Copy(tmp, io.LimitReader(&mediaContextReader{ctx: ctx, r: r}, maxImportBytes+1))
	if err != nil || size > maxImportBytes {
		return nil, nil, fmt.Errorf("读取导入文件失败或大小超限")
	}
	head := make([]byte, 4)
	n, err := tmp.ReadAt(head, 0)
	if err != nil && err != io.EOF {
		return nil, nil, err
	}
	if isZipPayload(head[:n]) {
		return readMediaExportZipWithBudget(ctx, tmp, size, defaultMediaImportLimits())
	}
	if size > maxImportJSONBytes {
		return nil, nil, fmt.Errorf("导入 JSON 文件过大")
	}
	if _, err := tmp.Seek(0, io.SeekStart); err != nil {
		return nil, nil, err
	}
	raw, err := io.ReadAll(&mediaContextReader{ctx: ctx, r: tmp})
	if err != nil {
		return nil, nil, err
	}
	var data MediaExportData
	if err := json.Unmarshal(raw, &data); err != nil {
		return nil, nil, fmt.Errorf("导入文件解析失败: %w", err)
	}
	return &data, nil, nil
}

func readMediaImportRequest(c *gin.Context, byteLimit int64) (*MediaExportData, []mediaImportedCover, error) {
	multipart := strings.HasPrefix(c.GetHeader("Content-Type"), "multipart/form-data")
	if !multipart {
		byteLimit = min(byteLimit, int64(maxImportJSONBytes))
	}
	c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, byteLimit)
	if multipart {
		defer func() {
			if c.Request.MultipartForm != nil {
				_ = c.Request.MultipartForm.RemoveAll()
			}
		}()
		if err := c.Request.ParseMultipartForm(8 << 20); err != nil {
			return nil, nil, fmt.Errorf("导入表单解析失败: %w", err)
		}
		fileHeader, err := c.FormFile("file")
		if err != nil {
			return nil, nil, fmt.Errorf("缺少 file 文件参数: %w", err)
		}
		f, err := fileHeader.Open()
		if err != nil {
			return nil, nil, err
		}
		defer f.Close()
		return readMediaImportFile(c.Request.Context(), f)
	}
	raw, err := io.ReadAll(&mediaContextReader{ctx: c.Request.Context(), r: c.Request.Body})
	if err != nil {
		return nil, nil, err
	}
	var data MediaExportData
	if err := json.Unmarshal(raw, &data); err != nil {
		return nil, nil, err
	}
	return &data, nil, nil
}

func readMediaZipEntry(ctx context.Context, f *zip.File, limit int64) ([]byte, error) {
	if limit < 0 || f.UncompressedSize64 > uint64(limit) {
		return nil, fmt.Errorf("压缩包条目解压大小超限: %s", f.Name)
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	rc, err := f.Open()
	if err != nil {
		return nil, err
	}
	defer rc.Close()
	raw, err := io.ReadAll(io.LimitReader(&mediaContextReader{ctx: ctx, r: rc}, limit+1))
	if err != nil || int64(len(raw)) > limit {
		return nil, fmt.Errorf("压缩包条目读取失败或大小超限: %s", f.Name)
	}
	return raw, nil
}

// rehashSeedFile reads one server-side file and recomputes its whole and piece hashes.
// cas 为 true 时忽略传入的 pieceSize，改用 CASSliceSize(size)：CAS 的分片由文件大小
// 唯一决定，用户配置对它无效；同时回填最终分片摘要。
func rehashSeedFile(c *gin.Context, user *model.User, sourcePath string, pieceSize int64, cas bool) (torrent.SeedFile, error) {
	var out torrent.SeedFile
	fullPath, err := user.JoinPath(sourcePath)
	if err != nil {
		return out, err
	}
	meta, err := op.GetNearestMeta(fullPath)
	if err != nil && !errors.Is(errors.Cause(err), errs.MetaNotFound) {
		return out, err
	}
	if !common.CanRead(user, meta, fullPath) {
		return out, errs.PermissionDenied
	}
	storage, actualPath, err := op.GetStorageAndActualPath(fullPath)
	if err != nil {
		return out, err
	}
	obj, err := op.Get(c.Request.Context(), storage, actualPath)
	if err != nil || obj.IsDir() {
		return out, fmt.Errorf("recalculate path must be a readable file: %s", sourcePath)
	}
	if obj.GetSize() < 0 || obj.GetSize() > maxTorrentGenFileSize {
		return out, fmt.Errorf("recalculate file exceeds 1GB limit: %s", sourcePath)
	}
	link, _, err := op.Link(c.Request.Context(), storage, actualPath, model.LinkArgs{})
	if err != nil {
		return out, fmt.Errorf("storage cannot stream %s: %v", sourcePath, err)
	}
	defer link.Close()
	rangeReader, err := stream.GetRangeReaderFromLink(obj.GetSize(), link)
	if err != nil {
		return out, fmt.Errorf("storage cannot stream %s", sourcePath)
	}
	rc, err := rangeReader.RangeRead(c.Request.Context(), http_range.Range{Length: obj.GetSize()})
	if err != nil {
		return out, err
	}
	defer rc.Close()
	if cas {
		pieceSize = torrent.CASSliceSize(obj.GetSize())
	}
	hasher := torrent.NewHashWriter(pieceSize, pieceSize, obj.GetSize())
	n, copyErr := io.Copy(hasher, io.LimitReader(rc, obj.GetSize()+1))
	if copyErr != nil {
		return out, fmt.Errorf("read %s: %w", sourcePath, copyErr)
	}
	if n != obj.GetSize() {
		return out, fmt.Errorf("read %s: got %d of %d bytes", sourcePath, n, obj.GetSize())
	}
	hasher.Finish()
	modified := ""
	if !obj.ModTime().IsZero() {
		modified = obj.ModTime().UTC().Format(time.RFC3339)
	}
	out = hasher.BuildSeedFile(stdpath.Base(sourcePath), modified)
	if cas {
		out.CASSliceMD5 = strings.ToLower(hasher.GetSliceMD5(out.Hashes.MD5))
	}
	return out, nil
}

