// removeUploadedCover 换封面时删掉上一张自定义封面。
// 只删本接口生成的文件（cover-<id>-<ts>.<ext>），不动刮削缩略图。
func removeUploadedCover(oldCover, newCover string) error {
	if oldCover == "" || oldCover == newCover {
		return nil
	}
	dir := thumbsDirName()
	prefix := "thumb:/" + dir + "/cover-"
	if !strings.HasPrefix(oldCover, prefix) {
		return nil
	}
	name := strings.TrimPrefix(oldCover, "thumb:/"+dir+"/")
	if name == "" || strings.ContainsAny(name, `/\:`) {
		return nil
	}
	referenced, err := db.HasMediaCoverReference(oldCover)
	if err != nil || referenced {
		return err
	}
	err = os.Remove(filepath.Join(scraper.RuntimeThumbRoot(dir), name))
	if os.IsNotExist(err) {
		return nil
	}
	return err
}

// resolveLocalFilePath 尝试把 OpenList 路径解析为宿主机文件系统的实际路径。
// 仅对本地驱动 (Local) 有效，其他驱动（云盘等）返回 false。
//
// 这是内存优化的关键路径：本地文件场景下让 ffmpeg 直接读文件，可以完全绕过
// HTTP /d 代理路径上的 net.Downloader 大块缓冲（默认每个 range 请求最高
// 占用 MaxBufferLimit = 系统内存 5%，多 chunk 并发 + 多 range 累计可达数 GB）。
func resolveLocalFilePath(rawPath string) (string, bool) {
	storage, actualPath, err := op.GetStorageAndActualPath(rawPath)
	if err != nil || storage == nil {
		return "", false
	}
	if storage.Config().Name != "Local" {
		return "", false
	}
	rooter, ok := storage.(driver.IRootPath)
	if !ok {
		return "", false
	}
	root := rooter.GetRootPath()
	if root == "" {
		return "", false
	}
	full := filepath.Join(root, actualPath)

	fi, err := os.Stat(full)
	if err != nil || fi.IsDir() {
		return "", false
	}
	return full, true
}

// resolveSeedTransitPath extracts the optional transit destination for a relayed save.
func resolveSeedTransitPath(req SeedQuickSaveReq) string {
	transitPath := strings.TrimSpace(req.TransitPath)
	if transitPath == "" && req.Options != nil {
		if mode, ok := req.Options["mode"].(string); ok && mode == "transfer" {
			if tp, ok := req.Options["transit_path"].(string); ok {
				transitPath = strings.TrimSpace(tp)
			}
		}
	}
	return transitPath
}

