func retryManagedTask[T task.TaskExtensionInfo](manager task.Manager[T], t T) error {
	if download, ok := any(t).(*tool.DownloadTask); ok {
		return download.RetryWith(func(next *tool.DownloadTask) {
			if next == download {
				manager.Retry(t.GetID())
				return
			}
			manager.Add(any(next).(T))
		})
	}
	manager.Retry(t.GetID())
	return nil
}

// safeCoverURL 校验封面地址的协议与域名（含重定向后的每一跳）
func safeCoverURL(u *url.URL) error {
	if u == nil {
		return fmt.Errorf("empty url")
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return fmt.Errorf("unsupported scheme")
	}
	if !hostAllowed(u.Hostname()) {
		return fmt.Errorf("host not allowed")
	}
	return nil
}

func safeMediaRelativePath(name string) bool {
	if name == "" || strings.ContainsAny(name, `\:`) || strings.ContainsRune(name, 0) ||
		strings.HasPrefix(name, "/") || filepath.IsAbs(name) || filepath.VolumeName(name) != "" {
		return false
	}
	for _, part := range strings.Split(name, "/") {
		if part == "" || part == "." || part == ".." || strings.TrimRight(part, " .") != part {
			return false
		}
	}
	return true
}

// sameSeedHost reports whether two URLs point at the same site.
//
// Comparison is on hostname plus the *effective* port (80/443 for http/https),
// not on url.URL.Host: a configured "https://pan.example.com" and an embedded
// "https://pan.example.com:443/..." are the same origin, and treating them as
// different silently drops otherwise valid sources.
func sameSeedHost(a, b *url.URL) bool {
	if !strings.EqualFold(a.Scheme, b.Scheme) {
		return false
	}
	if !strings.EqualFold(a.Hostname(), b.Hostname()) {
		return false
	}
	return effectivePort(a) == effectivePort(b)
}

