// saveSeedFilesToPath saves selected seed files into one target directory.
// progress 可为 nil；非 nil 时逐文件上报任务进度（任务本身只是展示载体）。
func saveSeedFilesToPath(c *gin.Context, user *model.User, seed *torrent.Seed, req SeedQuickSaveReq, dstPath string, rapidOnly bool, allowOffline bool, progress *fs.SeedSaveTask) ([]gin.H, string, string, error) {
	results := make([]gin.H, 0, len(seed.Files))

	ctx := c.Request.Context()
	if progress != nil {
		ctx = progress.Ctx()
	}
	fullPath, err := user.JoinPath(dstPath)
	if err != nil {
		return nil, "", "", err
	}
	meta, err := op.GetNearestMeta(fullPath)
	if err != nil && !errors.Is(errors.Cause(err), errs.MetaNotFound) {
		return nil, "", "", err
	}
	if (!user.CanWriteContent() && !common.CanWriteContentBypassUserPerms(meta, fullPath)) || !common.CanWrite(user, meta, fullPath) {
		return nil, "", "", errs.PermissionDenied
	}
	storage, actualPath, err := op.GetStorageAndActualPath(fullPath)
	if err != nil {
		return nil, "", "", err
	}
	dstDir, err := op.Get(ctx, storage, actualPath)
	if err != nil || !dstDir.IsDir() {
		return nil, "", "", errs.NotFolder
	}
	driverName, mountPath := "", ""
	if mounted := storage.GetStorage(); mounted != nil {
		driverName = strings.TrimSpace(mounted.Driver)
		mountPath = strings.TrimSpace(mounted.MountPath)
	}
	selected := make(map[string]struct{}, len(req.Files))
	for _, name := range req.Files {
		selected[name] = struct{}{}
	}
	selectedIndexes := make(map[int]struct{}, len(req.SelectedFiles))
	for _, index := range req.SelectedFiles {
		if index < 0 || index >= len(seed.Files) {
			return nil, "", "", fmt.Errorf("selected_files contains an invalid index")
		}
		selectedIndexes[index] = struct{}{}
	}
	rapidUploader := seedRapidUploaderFor(storage)
	_, putURL := storage.(driver.PutURL)
	_, putURLResult := storage.(driver.PutURLResult)

	pending := make([]torrent.SeedFile, 0, len(seed.Files))
	for index, file := range seed.Files {
		if len(selected) > 0 {
			if _, ok := selected[file.Path]; !ok {
				continue
			}
		} else if len(selectedIndexes) > 0 {
			if _, ok := selectedIndexes[index]; !ok {
				continue
			}
		}
		pending = append(pending, file)
	}
	for i, file := range pending {

		if err := ctx.Err(); err != nil {
			return results, driverName, mountPath, err
		}
		name := stdpath.Base(file.Path)
		if progress != nil {

			progress.Report(i+1, len(pending), name, "saving")
		}
		var rapidErr error
		if rapidUploader != nil {
			if blocker := seedRapidUploadBlocker(file); blocker != "" {
				rapidErr = errors.New(blocker)
			} else if seedFileSupportsRapidUpload(rapidUploader, file) {
				if rapidReq := buildSeedFileRapidUploadRequest(seed, file, seedContentOpener(seed, file, ctx)); rapidReq != nil {
					var obj model.Obj
					obj, rapidErr = rapidUploader.RapidUploadByHashes(ctx, dstDir, rapidReq, req.Overwrite)
					if rapidErr == nil {
						results = append(results, gin.H{"path": file.Path, "name": obj.GetName(), "method": "rapid_upload"})
						continue
					}
				}
			}
		}
		if err := ctx.Err(); err != nil {
			return results, driverName, mountPath, err
		}
		if rapidOnly {

			reason := "target driver cannot reuse the available hashes"
			if rapidErr != nil {
				reason = fmt.Sprintf("rapid upload failed: %v", rapidErr)
			}
			results = append(results, gin.H{"path": file.Path, "name": name, "method": "unavailable", "error": reason})

			if rapidErr != nil && errors.Is(rapidErr, errs.DailyFlowLimitExceeded) {
				for _, rest := range pending[i+1:] {
					results = append(results, gin.H{"path": rest.Path, "name": stdpath.Base(rest.Path), "method": "unavailable", "error": reason})
				}
				break
			}
			continue
		}
		source := firstUsableSeedSource(file)
		if source == "" {
			results = append(results, gin.H{"path": file.Path, "name": name, "method": "unavailable", "error": "no usable source URL or compatible rapid-upload hashes"})
			continue
		}
		if putURL || putURLResult {
			if putErr := fs.PutURL(ctx, fullPath, name, source); putErr == nil {
				results = append(results, gin.H{"path": file.Path, "name": name, "method": "put_url"})
				continue
			}
		}
		if err := ctx.Err(); err != nil {
			return results, driverName, mountPath, err
		}
		if !allowOffline {
			results = append(results, gin.H{"path": file.Path, "name": name, "method": "offline_download", "error": "transit requires a synchronous intermediate save (rapid upload or PutURL)"})
			continue
		}
		if !user.CanAddOfflineDownloadTasks() {
			results = append(results, gin.H{"path": file.Path, "name": name, "method": "offline_download", "error": "offline download permission is required"})
			continue
		}
		if req.Tool == "" {
			results = append(results, gin.H{"path": file.Path, "name": name, "method": "offline_download", "error": "offline download tool is required"})
			continue
		}
		t, addErr := tool.AddURL(ctx, &tool.AddURLArgs{URL: source, DstDirPath: fullPath, Tool: req.Tool, DeletePolicy: tool.DeletePolicy(req.DeletePolicy)})
		if addErr != nil {
			results = append(results, gin.H{"path": file.Path, "name": name, "method": "offline_download", "error": addErr.Error()})
			continue
		}
		result := gin.H{"path": file.Path, "name": name, "method": "offline_download"}
		if t != nil {
			result["task"] = getTaskInfo(t)
		}
		results = append(results, result)
	}
	return results, driverName, mountPath, nil
}

// saveUploadedCover 把上传的图片写入缩略图目录，返回 cover 字段值（thumb:/<dir>/<name>）
func saveUploadedCover(itemID uint, data []byte) (string, error) {
	ext := coverFileExt(data)
	if ext == "" {
		return "", fmt.Errorf("不支持的图片格式（仅支持 jpg / png / gif / webp）")
	}
	dir := thumbsDirName()
	root := scraper.RuntimeThumbRoot(dir)
	if err := os.MkdirAll(root, 0o755); err != nil {
		return "", err
	}
	name := fmt.Sprintf("cover-%d-%d%s", itemID, time.Now().UnixNano(), ext)
	if err := os.WriteFile(filepath.Join(root, name), data, 0o644); err != nil {
		return "", err
	}
	return "thumb:/" + dir + "/" + name, nil
}

// seedContentOpener returns a lazy content provider for a seed file.
//
// The source bytes are fetched from the file's first usable source URL, but
// only on the first call, letting hash-only drivers (e.g. 189pc) skip content
// entirely. Requests are deliberately anonymous and routed through
// seedSourceHTTPClient so redirects are re-validated (see its doc comment).
//
// The returned streamer is backed by a range reader rather than a fully
// buffered copy: drivers such as aliyundrive_open and quark_open only read a
// small proof window, and 115 reads a 128KiB prefix, so buffering up to 1GB in
// memory would be pure waste.
func seedContentOpener(seed *torrent.Seed, file torrent.SeedFile, ctx context.Context) func() (model.FileStreamer, error) {
	source := firstUsableSeedSource(file)
	if source == "" {
		return nil
	}
	if ctx == nil {
		ctx = context.Background()
	}
	return func() (model.FileStreamer, error) {
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, source, nil)
		if err != nil {
			return nil, err
		}
		resp, err := seedSourceHTTPClient.Do(req)
		if err != nil {
			return nil, fmt.Errorf("failed to download seed content: %w", err)
		}
		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
			resp.Body.Close()
			return nil, fmt.Errorf("failed to download seed content: HTTP %d", resp.StatusCode)
		}

		size := resp.ContentLength
		if size < 0 {
			size = file.Size
		}
		if size > maxTorrentGenFileSize {
			resp.Body.Close()
			return nil, fmt.Errorf("seed content exceeds the size limit: %d", size)
		}
		if file.Size > 0 && resp.ContentLength >= 0 && resp.ContentLength != file.Size {
			resp.Body.Close()
			return nil, fmt.Errorf("seed content size mismatch: expected %d, got %d", file.Size, resp.ContentLength)
		}

		obj := &model.Object{
			Name:		stdpath.Base(file.Path),
			Size:		size,
			Modified:	time.Now(),
			IsFolder:	false,
		}
		fs := &stream.FileStream{
			Ctx:	ctx,
			Obj:	obj,
			Reader:	io.LimitReader(resp.Body, maxTorrentGenFileSize),
		}

		fs.Add(resp.Body)
		return fs, nil
	}
}

// seedConversionStates 给出每个目标格式的可行性。
//
// 目标格式等于当前格式时直接标为可行：种子本身就是这个格式，不存在「转换」；
// 而 DiagnoseConversion 是按文件 pieces 判断能否重新编码成整包 torrent 的，
// 对本来就合法的 .torrent（pieces 跨文件、按文件拆不开）会误报不可转换。
func seedConversionStates(seed *torrent.Seed, sourceFormat string) gin.H {
	states := make(gin.H, 3)
	source := strings.ToLower(strings.TrimPrefix(strings.TrimSpace(sourceFormat), "."))
	for _, format := range []string{"oss", "torrent", "cas"} {
		if format == source {
			states[format] = gin.H{"feasible": true, "missing": []string{}}
			continue
		}
		missing := torrent.DiagnoseConversion(seed, format)
		states[format] = gin.H{"feasible": len(missing) == 0, "missing": missing}
	}
	return states
}

func seedConvertMatrix(requested *SeedHashMatrix, target string) *SeedHashMatrix {
	if requested == nil {
		return nil
	}
	matrix := *requested
	if target == "torrent" {
		matrix.SHA1 = SeedHashSelection{Whole: true, Pieces: true}
	}
	if target == "cas" {
		matrix.MD5 = SeedHashSelection{Whole: true, Pieces: true}
	}
	return &matrix
}

func seedConvertMatrixMissing(seed *torrent.Seed, matrix SeedHashMatrix) bool {
	for _, file := range seed.Files {
		if (matrix.MD5.Whole && file.Hashes.MD5 == "") ||
			(matrix.SHA1.Whole && file.Hashes.SHA1 == "") ||
			(matrix.SHA256.Whole && file.Hashes.SHA256 == "") {
			return true
		}
		if file.Size == 0 {
			continue
		}
		pieces := file.Hashes.Pieces
		if (matrix.MD5.Pieces && (pieces == nil || len(pieces.MD5) == 0)) ||
			(matrix.SHA1.Pieces && len(seed.GlobalPieces) == 0 && (pieces == nil || len(pieces.SHA1) == 0)) ||
			(matrix.SHA256.Pieces && (pieces == nil || len(pieces.SHA256) == 0)) {
			return true
		}
	}
	return false
}

// seedConvertTargets 归一化请求里的目标格式列表（去重、bt -> torrent、最多三个）。
func seedConvertTargets(req SeedConvertReq) []string {
	raw := req.Formats
	if len(raw) == 0 {
		switch {
		case req.TargetFormat != "":
			raw = []string{req.TargetFormat}
		case req.Format != "":
			raw = []string{req.Format}
		}
	}
	seen := make(map[string]bool, len(raw))
	out := make([]string, 0, len(raw))
	for _, value := range raw {
		format := strings.ToLower(strings.TrimPrefix(strings.TrimSpace(value), "."))
		if format == "bt" {
			format = "torrent"
		}
		if format != "torrent" && format != "cas" && format != "oss" {
			continue
		}
		if seen[format] {
			continue
		}
		seen[format] = true
		out = append(out, format)
		if len(out) == 3 {
			break
		}
	}
	return out
}

func seedDiagnostics(seed *torrent.Seed) gin.H {
	return gin.H{
		"oss":		torrent.DiagnoseConversion(seed, "oss"),
		"torrent":	torrent.DiagnoseConversion(seed, "torrent"),
		"cas":		torrent.DiagnoseConversion(seed, "cas"),
	}
}

// seedFileSupportsRapidUpload reports whether a seed file carries enough hash
// metadata for the given rapid-upload driver to attempt an instant upload.
func seedFileSupportsRapidUpload(uploader driver.SeedRapidUploader, file torrent.SeedFile) bool {
	if uploader == nil {
		return false
	}
	hasMD5 := file.Hashes.MD5 != ""
	hasSHA1 := file.Hashes.SHA1 != ""
	for _, ht := range uploader.RapidHashAlgos() {
		switch ht.Name {
		case utils.MD5.Name:
			if hasMD5 {
				return true
			}
		case utils.SHA1.Name:
			if hasSHA1 {
				return true
			}
		}
	}
	return false
}

func seedMatrixEmpty(matrix SeedHashMatrix) bool {
	return !matrix.MD5.Whole && !matrix.MD5.Pieces && !matrix.SHA1.Whole && !matrix.SHA1.Pieces && !matrix.SHA256.Whole && !matrix.SHA256.Pieces
}

func seedPieceSize(c *gin.Context) int64 {
	value := c.GetHeader("X-Seed-Piece-Size")
	if value == "" {
		return torrent.DefaultPieceSize
	}
	size, err := strconv.ParseInt(value, 10, 64)
	if err != nil || size <= 0 || size > 1<<30 {
		return torrent.DefaultPieceSize
	}
	return size
}

// seedRapidUploadBlocker returns why rapid upload must be skipped for this seed
// file ("" means it may be attempted).
//
// 种子可以描述任意文件，包括另一个种子容器：拿 .cas 再生成 .cas 时，载荷里的
// name 就是 .cas 自己。这类种子秒传上去只会在目标目录再造一个同名 .cas，
// 看起来像「秒传成功但只有一个 cas 文件」，所以先拦下来。
func seedRapidUploadBlocker(file torrent.SeedFile) string {
	name := stdpath.Base(file.Path)
	if !fs.IsSeedContainerName(name) {
		return ""
	}
	return fmt.Sprintf("this seed describes a seed file itself (%s), not the content inside it; use the seed that describes the target file", name)
}

// seedRapidUploaderFor probes a storage driver for the generic
// driver.SeedRapidUploader capability. It returns nil when the driver does not
// support hash-driven rapid upload (秒传/CAS).
func seedRapidUploaderFor(storage driver.Driver) driver.SeedRapidUploader {
	if storage == nil {
		return nil
	}
	if u, ok := storage.(driver.SeedRapidUploader); ok {
		return u
	}
	return nil
}

// seedSaveErrorCode maps a save error to an HTTP status code.
func seedSaveErrorCode(err error) int {

	if errors.Is(err, context.Canceled) {
		return 499
	}
	if errors.Is(errors.Cause(err), errs.PermissionDenied) {
		return 403
	}
	if errors.Is(errors.Cause(err), errs.NotFolder) || errors.Is(errors.Cause(err), errs.ObjectNotFound) {
		return 400
	}
	return 500
}

func seedSaveResultsError(results []gin.H) error {
	failed := 0
	for _, result := range results {
		message, _ := result["error"].(string)
		if result["method"] == "unavailable" || message != "" {
			failed++
		}
	}
	if failed > 0 {
		return fmt.Errorf("%d/%d seed files failed to save", failed, len(results))
	}
	return nil
}

// seedSidecarFormats 返回本次上传要生成的种子格式串。
// 请求头优先（X-Seed-Sidecars / X-Seed-Format），其次全局策略。
func seedSidecarFormats(c *gin.Context) string {
	formatsHeader := strings.TrimSpace(c.GetHeader("X-Seed-Sidecars"))
	if formatsHeader == "" {
		formatsHeader = strings.TrimSpace(c.GetHeader("X-Seed-Format"))
	}
	if formatsHeader == "" {
		formatsHeader = configuredSeedFormats()
	}
	return formatsHeader
}

func seedSidecarPaths(filePath string) []string {
	return []string{filePath + ".oss", filePath + ".torrent", filePath + ".cas", filePath + ".cas.torrent"}
}

// seedSidecarWantsCAS reports whether this upload asks for a .cas sidecar.
func seedSidecarWantsCAS(c *gin.Context) bool {
	for _, format := range strings.Split(strings.ToLower(seedSidecarFormats(c)), ",") {
		if strings.TrimSpace(format) == "cas" {
			return true
		}
	}
	return false
}

// seedSiteConfig returns the parsed seed_site_url, or an error when it is unset
// or malformed. All seed source validation is relative to this origin.
func seedSiteConfig() (*url.URL, error) {
	configured := strings.TrimSpace(seedSiteURLProvider())
	if configured == "" {
		return nil, fmt.Errorf("seed_site_url is not configured")
	}
	site, err := url.Parse(configured)
	if err != nil {
		return nil, fmt.Errorf("failed to parse seed_site_url: %w", err)
	}
	if site.Scheme == "" || site.Hostname() == "" {
		return nil, fmt.Errorf("seed_site_url is missing scheme or host")
	}
	return site, nil
}

func seedTotalSize(seed *torrent.Seed) int64 {
	var total int64
	for _, file := range seed.Files {
		total += file.Size
	}
	return total
}

func selectSeedConvertFiles(seed *torrent.Seed, indexes []int) (bool, error) {
	if indexes == nil {
		return false, nil
	}
	if len(indexes) == 0 {
		return false, fmt.Errorf("at least one seed file must be selected")
	}
	selected := make(map[int]bool, len(indexes))
	for _, index := range indexes {
		if index < 0 || index >= len(seed.Files) {
			return false, fmt.Errorf("selected_files contains an invalid index")
		}
		selected[index] = true
	}
	if len(selected) == len(seed.Files) {
		return false, nil
	}
	files := make([]torrent.SeedFile, 0, len(selected))
	for index, file := range seed.Files {
		if selected[index] {
			files = append(files, file)
		}
	}
	seed.Files = files
	seed.GlobalPieces = nil
	seed.AvailableHashes = nil
	seed.AvailablePieceHashes = nil
	return true, nil
}

// setSafeImageHeaders 为用户可影响内容的图片响应加上防 XSS 头。
func setSafeImageHeaders(c *gin.Context) {
	c.Header("X-Content-Type-Options", "nosniff")
	c.Header("Content-Disposition", `inline; filename="cover"`)
	c.Header("Content-Security-Policy", "default-src 'none'; sandbox")
}

func shouldGenerateUploadSeed(c *gin.Context, path string) bool {
	if strings.TrimSpace(c.GetHeader("X-Seed-Sidecars")) != "" {
		return true
	}
	policy := strings.ToLower(strings.TrimSpace(c.GetHeader("X-Generate-Seed")))
	if policy != "" && policy != "inherit" {
		return policy == "on" || policy == "true" || policy == "1"
	}
	if storage := op.GetBalancedStorage(path); storage != nil {
		policy = strings.ToLower(strings.TrimSpace(storage.GetStorage().SeedPolicy))
	}
	if policy == "" || policy == "inherit" {
		policy = strings.ToLower(setting.GetStr(conf.SeedAutoGeneratePolicy, "off"))
	}
	return (policy == "on" || policy == "true" || policy == "1") && configuredSeedFormats() != ""
}

