// tokenMatches 恒定时间比较凭据，避免按字节比较造成的时序侧信道
func tokenMatches(expected, got string) bool {
	if expected == "" || got == "" {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(expected), []byte(got)) == 1
}

// transferSeedViaTransit first saves to an intermediate directory then relays to the final target.
func transferSeedViaTransit(c *gin.Context, user *model.User, seed *torrent.Seed, req SeedQuickSaveReq, transitPath string) {

	progress := fs.NewSeedSaveTask(c.Request.Context(), user, "transfer seed "+seed.Name)
	fail := func(err error, code int) {
		progress.Finish(err)
		common.ErrorResp(c, err, code)
	}
	if !user.CanCopy() {
		fail(errs.PermissionDenied, 403)
		return
	}
	transitResults, _, _, err := saveSeedFilesToPath(c, user, seed, req, transitPath, false, false, progress)
	if err != nil {
		fail(err, seedSaveErrorCode(err))
		return
	}
	finalDst, err := user.JoinPath(req.Path)
	if err != nil {
		fail(err, 403)
		return
	}
	finalMeta, err := op.GetNearestMeta(finalDst)
	if err != nil && !errors.Is(errors.Cause(err), errs.MetaNotFound) {
		fail(err, 500)
		return
	}
	if (!user.CanWriteContent() && !common.CanWriteContentBypassUserPerms(finalMeta, finalDst)) || !common.CanWrite(user, finalMeta, finalDst) {
		fail(errs.PermissionDenied, 403)
		return
	}
	transitFullPath, err := user.JoinPath(transitPath)
	if err != nil {
		fail(err, 403)
		return
	}
	finalResults := make([]gin.H, 0, len(transitResults))
	relayTotal := len(transitResults)

	failed := 0
	for i, res := range transitResults {
		if err := progress.Ctx().Err(); err != nil {
			fail(err, seedSaveErrorCode(err))
			return
		}
		method, _ := res["method"].(string)
		if method == "unavailable" || res["error"] != nil {
			failed++
			finalResults = append(finalResults, res)
			continue
		}
		name, _ := res["name"].(string)
		if name == "" {
			continue
		}

		if method == "offline_download" {
			failed++
			finalResults = append(finalResults, gin.H{"path": res["path"], "name": name, "method": "transfer", "error": "transit requires a synchronous intermediate save (rapid upload or PutURL)"})
			continue
		}
		progress.Report(i+1, relayTotal, name, "transferring")
		srcObjPath := stdpath.Join(transitFullPath, name)
		_, copyErr := fs.Copy(context.WithValue(progress.Ctx(), conf.NoTaskKey, struct{}{}), srcObjPath, finalDst)
		if err := progress.Ctx().Err(); err != nil {
			fail(err, seedSaveErrorCode(err))
			return
		}
		if copyErr != nil {
			failed++
			finalResults = append(finalResults, gin.H{"path": res["path"], "name": name, "method": "transfer", "error": copyErr.Error()})
			continue
		}
		finalResults = append(finalResults, gin.H{"path": res["path"], "name": name, "method": "transfer"})
	}
	if failed > 0 {

		progress.Finish(fmt.Errorf("%d/%d seed files failed to transfer", failed, relayTotal))
	} else {
		progress.Finish(nil)
	}
	common.SuccessResp(c, gin.H{"results": finalResults})
}

func trimFloat(v float64) string {
	s := strconv.FormatFloat(v, 'f', 1, 64)
	return strings.TrimSuffix(s, ".0")
}

// trustedInternalBaseURL 返回供服务端 ffmpeg 访问本站 /d 接口的可信基址，不读取任何请求头。
// 优先使用管理员配置的 site_url；未配置时回环到本机实际监听的 HTTP 端口。
// 两者都不可用（例如仅监听 Unix socket）时返回空串，调用方应拒绝转码。
func trustedInternalBaseURL() string {
	if site := strings.TrimSuffix(conf.Conf.SiteURL, "/"); strings.HasPrefix(site, "http") {
		return site
	}
	if p := conf.Conf.Scheme.HttpPort; p > 0 {
		return fmt.Sprintf("http://127.0.0.1:%d", p)
	}
	return ""
}

// uploadSeedSliceSize 返回上传时计算哈希应使用的分片大小。
// CAS 的分片由文件大小唯一决定（CASSliceSize），请求头里的 piece size 对它无效；
// 其它格式沿用请求头/默认值。
func uploadSeedSliceSize(c *gin.Context, fileSize int64) int64 {
	if seedSidecarWantsCAS(c) {
		return torrent.CASSliceSize(fileSize)
	}
	return seedPieceSize(c)
}

// userPathPrefix 返回用于 SQL 前缀过滤的用户目录，全盘用户返回空串
func userPathPrefix(user *model.User) string {
	if user == nil {
		return ""
	}
	base := utils.FixAndCleanPath(user.BasePath)
	if base == "" || base == "/" {
		return ""
	}
	return base
}

func validHide(hide string) (string, error) {
	rs := strings.SplitSeq(hide, "\n")
	for r := range rs {
		_, err := regexp2.Compile(r, regexp2.None)
		if err != nil {
			return r, err
		}
	}
	return "", nil
}

// validateJSONArray 校验字段是否为合法 JSON 数组（空串允许）
func validateJSONArray(name, raw string) error {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return nil
	}
	var arr []json.RawMessage
	if err := json.Unmarshal([]byte(raw), &arr); err != nil {
		return fmt.Errorf("%s 必须是 JSON 数组", name)
	}
	return nil
}

func validateOfflineDownloadStorage(c *gin.Context, tempDir, nativeTool string) bool {
	if tempDir == "" {
		return true
	}
	storage, _, err := op.GetStorageAndActualPath(tempDir)
	if err != nil {
		common.ErrorStrResp(c, "storage does not exists", 400)
		return false
	}
	if storage.Config().CheckStatus && storage.GetStorage().Status != op.WORK {
		common.ErrorStrResp(c, "storage not init: "+storage.GetStorage().Status, 400)
		return false
	}
	if tool.NativeToolName(storage) != nativeTool {
		common.ErrorStrResp(c, "unsupported storage driver for offline download, only "+nativeTool+" is supported", 400)
		return false
	}
	return true
}

// validateParsedTorrent checks that basic torrent invariants hold.
func validateParsedTorrent(t *torrent.Torrent) error {
	if len(t.Info.Pieces)%20 != 0 {
		return fmt.Errorf("invalid torrent pieces: length must be a multiple of 20")
	}
	return nil
}

// validateSeedHost checks that a seed source URL belongs to the configured site
// and carries no embedded credentials. It is shared by the pre-flight
// validation and by the redirect guard, so both enforce identical rules.
func validateSeedHost(u *url.URL) error {
	if u == nil {
		return fmt.Errorf("empty URL")
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return fmt.Errorf("unsupported scheme %q", u.Scheme)
	}
	if u.User != nil {
		return fmt.Errorf("seed source must not carry user credentials")
	}
	site, err := seedSiteConfig()
	if err != nil {
		return err
	}
	if !sameSeedHost(u, site) {
		return fmt.Errorf("seed source host %q does not match the configured site %q", u.Host, site.Host)
	}
	return nil
}

// validateSeedSource enforces the metadata contract for editable share/direct sources.
func validateSeedSource(src torrent.SeedSource) error {
	if src.Type != "openlist-direct" && src.Type != "openlist-share" {
		return fmt.Errorf("unsupported seed source type %q", src.Type)
	}
	u, err := url.Parse(src.URL)
	if err != nil {
		return fmt.Errorf("invalid seed source URL for %q", src.Type)
	}
	if err := validateSeedHost(u); err != nil {
		return err
	}
	if src.Type == "openlist-direct" && !strings.HasPrefix(u.EscapedPath(), "/d/") {
		return fmt.Errorf("openlist-direct source URL must start with /d/")
	}
	if src.Type == "openlist-share" && !strings.HasPrefix(u.EscapedPath(), "/sd/") {
		return fmt.Errorf("openlist-share source URL must start with /sd/")
	}
	return nil
}

func validateSharingID(id string) error {
	if len([]rune(id)) > 64 {
		return errors.New("share id must be at most 64 characters")
	}
	if !validSharingID.MatchString(id) {
		return errors.New("share id can only contain letters, numbers, underscores, hyphens, and CJK characters")
	}
	return nil
}

// validateUploadSeedRequest rejects invalid seed sidecar headers before the
// main file is stored, so a bad X-Seed-* header cannot leave a partially
// uploaded file behind.
func validateUploadSeedRequest(c *gin.Context) error {
	if _, err := fs.NormalizeSeedFormats(strings.Split(seedSidecarFormats(c), ",")); err != nil {
		return err
	}
	if raw := strings.TrimSpace(c.GetHeader("X-Seed-Hash-Matrix")); raw != "" {
		var matrix SeedHashMatrix
		if err := json.Unmarshal([]byte(raw), &matrix); err != nil {
			return fmt.Errorf("invalid seed hash matrix: %w", err)
		}
	}
	return nil
}

func verifyState(clientID, ip, state string) bool {
	value, ok := stateCache.Get(_keyState(clientID, state))
	return ok && value == ip
}

// writeMediaExportZip 把导出数据打包成 zip：JSON + covers/。
// 会就地改写 items[].cover 为压缩包内的相对路径。
func writeMediaExportZip(ctx context.Context, w io.Writer, data *MediaExportData) error {
	covers := fetchCovers(ctx, data.Items)
	if err := ctx.Err(); err != nil {
		return err
	}
	zw := zip.NewWriter(&mediaContextWriter{ctx: ctx, w: w})
	defer zw.Close()
	used := map[string]bool{}
	for i := range data.Items {
		if err := ctx.Err(); err != nil {
			return err
		}
		blob, ok := covers[i]
		if !ok {
			continue
		}
		ext := blob.ext
		id := data.Items[i].ID
		name := fmt.Sprintf("item-%d%s", id, ext)
		for n := 1; used[name]; n++ {
			name = fmt.Sprintf("item-%d-%d%s", id, n, ext)
		}
		used[name] = true
		f, err := zw.Create(mediaExportCoverDir + "/" + name)
		if err != nil {
			return err
		}
		if _, err := f.Write(blob.data); err != nil {
			return err
		}
		data.Items[i].Cover = mediaExportCoverDir + "/" + name
	}

	f, err := zw.Create(mediaExportJSONName)
	if err != nil {
		return err
	}
	if err := json.NewEncoder(f).Encode(data); err != nil {
		return err
	}
	return zw.Close()
}

func writeUploadSeedSidecar(c *gin.Context, dir, name string, expectedSize int64, hasher *torrent.HashWriter) error {
	if hasher == nil {
		return nil
	}
	hasher.Finish()
	if expectedSize >= 0 && hasher.GetTotalWritten() != expectedSize {
		return fmt.Errorf("seed sidecar requires a complete stream: read %d of %d bytes", hasher.GetTotalWritten(), expectedSize)
	}
	seed := torrent.NewSeed(name, "OpenList", uploadSeedSliceSize(c, expectedSize))
	formats, err := fs.NormalizeSeedFormats(strings.Split(seedSidecarFormats(c), ","))
	if err != nil {
		return err
	}
	matrix := SeedHashMatrix{}
	if rawMatrix := strings.TrimSpace(c.GetHeader("X-Seed-Hash-Matrix")); rawMatrix != "" {
		if err = json.Unmarshal([]byte(rawMatrix), &matrix); err != nil {
			return fmt.Errorf("invalid seed hash matrix: %w", err)
		}
	}
	matrix = normalizedSeedMatrix(matrix, formats)
	seedFile := hasher.BuildSeedFile(name, getLastModified(c).UTC().Format(time.RFC3339))
	applySeedMatrix(&seedFile, matrix)
	seed.Files = []torrent.SeedFile{seedFile}
	seen := make(map[string]struct{}, 3)
	for _, rawFormat := range formats {
		format := strings.ToLower(strings.TrimPrefix(strings.TrimSpace(rawFormat), "."))
		if format == "bt" {
			format = "torrent"
		}
		if _, exists := seen[format]; exists {
			continue
		}
		seen[format] = struct{}{}
		data, err := fs.EncodeGeneratedSeed(seed, format, hasher.GetPieceHashes())
		if err != nil {
			return fmt.Errorf("generate %s seed sidecar: %w", format, err)
		}
		sidecar := &stream.FileStream{
			Ctx:	c.Request.Context(),
			Obj:	&model.Object{Name: name + "." + format, Size: int64(len(data)), Modified: time.Now()},
			Reader:	bytes.NewReader(data), Mimetype: "application/octet-stream",
		}
		if err = fs.PutDirectly(c.Request.Context(), dir, sidecar, true); err != nil {
			return fmt.Errorf("upload %s seed sidecar: %w", format, err)
		}
	}
	return nil
}
